>Verification Code</label>\\n                                <div class=\\"d-flex align-items-center\\">\\n                                    <field required=\\"True\\" name=\\"code\\" autocomplete=\\"off\\" class=\\"o_field_highlight px-0 me-2\\" placeholder=\\"e.g. 123456\\"/>\\n                                </div>\\n                            </div>\\n                        </div>\\n                    </div>\\n                </sheet>\\n                <footer>\\n                    <button type=\\"object\\" name=\\"enable\\" class=\\"btn btn-primary\\" string=\\"Activate\\" data-hotkey=\\"q\\"/>\\n                    <button string=\\"Cancel\\" special=\\"cancel\\" data-hotkey=\\"x\\"/>\\n                </footer>\\n            </form>"}	<?xml version="1.0"?>\n<form>\n                <sheet>\n                    <div class="o_auth_totp_enable_2FA container">\n                        <div class="mb-3 w-100">\n                            <h3 class="fw-bold">Authenticator App Setup</h3>\n                            <ul>\n                                <div class="d-md-none d-block">\n                                    <li>\n                                        <field class="text-wrap" name="url" widget="url" options="{'website_path': True}" text="Click on this link to open your authenticator app"/></li>\n                                </div>\n                                <li>\n                                    <div class="d-flex align-items-center flex-wrap">\n                                        <span class="d-md-none d-block">Or install an authenticator app</span>\n                                        <span class="d-none d-md-block">Install an authenticator app on your mobile device</span>\n                                        <div class="d-block d-md-none">\n                                            <a href="https://play.google.com/store/search?q=authenticator&amp;c=apps" class="mx-2" target="blank">\n                                 