224	16	\N	1	1	Barcode Nomenclatures	barcode.nomenclature	\N	form	barcodes/views/barcodes_view.xml	primary	{"en_US": "<form string=\\"Barcode Nomenclature\\">\\n                    <sheet>\\n                        <group name=\\"general_attributes\\" col=\\"4\\">\\n                            <field name=\\"name\\"/>\\n                            <field name=\\"upc_ean_conv\\"/>\\n                        </group>\\n                        <div>\\n                            <p>\\n                                <i>Barcodes Nomenclatures</i> define how barcodes are recognized and categorized.\\n                                When a barcode is scanned it is associated to the <i>first</i> rule with a matching\\n                                pattern. The pattern syntax is that of regular expression, and a barcode is matched\\n                                if the regular expression matches a prefix of the barcode.\\n                            </p><p>\\n                                Patterns can also define how numerical values, such as weight or price, can be\\n                                encoded into the barcode. They are indicated by <code>{NNN}</code> where the N's\\n                                define where the number's digits are encoded. Floats are also supported with the\\n                                decimals indicated with D's, such as <code>{NNNDD}</code>. In these cases,\\n                                the barcode field on the associated records <i>must</i> show these digits as\\n                                zeroes.\\n                            </p>\\n                        </div>\\n                        <field name=\\"rule_ids\\">\\n                            <tree string=\\"Tables\\">\\n                                <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                <field name=\\"name\\"/>\\n                                <field name=\\"type\\"/>\\n                                <field name=\\"encoding\\"/>\\n                                <field name=\\"pattern\\"/>\\n                            </tree>\\n                        </field>\\n                    </sheet>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Barcode Nomenclature">\n                    <sheet>\n                        <group name="general_attributes" col="4">\n                            <field name="name"/>\n                            <field name="upc_ean_conv"/>\n                        </group>\n                        <div>\n                            <p>\n                                <i>Barcodes Nomenclatures</i> define how barcodes are recognized and categorized.\n                                When a barcode is scanned it is associated to the <i>first</i> rule with a matching\n                                pattern. The pattern syntax is that of regular expression, and a barcode is matched\n                                if the regular expression matches a prefix of the barcode.\n                            </p><p>\n                                Patterns can also define how numerical values, such as weight or price, can be\n                                encoded into the barcode. They are indicated by <code>{NNN}</code> where the N's\n                                define where the number's digits are encoded. Floats are also supported with the\n                                decimals indicated with D's, such as <code>{NNNDD}</code>. In these cases,\n                                the barcode field on the associated records <i>must</i> show these digits as\n                                zeroes.\n                            </p>\n                        </div>\n                        <field name="rule_ids">\n                            <tree string="Tables">\n                                <field name="sequence" widget="handle"/>\n                                <field name="name"/>\n                                <field name="type"/>\n                                <field name="encoding"/>\n                                <field name="pattern"/>\n                            </tree>\n                        </field>\n                    </sheet>\n                </form>\n            	f	t	2026-09-17 06:40:08.938934	2026-09-17 06:40:08.938934	\N
