y=\\"x\\"/>\\n                </footer>\\n            </form>"}	<?xml version="1.0"?>\n<form>\n                <!-- Field present for correct default_get behavior -->\n                <field name="letter_id" invisible="1"/>\n                <p>The customer address is not complete. Update the address here and re-send the letter.</p>\n                <group>\n                    <label for="partner_id" string="Address"/>\n                    <div class="o_address_format">\n                        <field name="partner_id" readonly="1" options="{'no_open': True}" force_save="1"/>\n                        <field name="street" placeholder="Street..." class="o_address_street"/>\n                        <field name="street2" placeholder="Street 2..." class="o_address_street"/>\n                        <field name="city" placeholder="City" class="o_address_city"/>\n                        <field name="state_id" class="o_address_state" placeholder="State" options="{&quot;no_open&quot;: True}"/>\n                        <field name="zip" placeholder="ZIP" class="o_address_zip"/>\n                        <field name="country_id" placeholder="Country" class="o_address_country" options="{&quot;no_open&quot;: True, &quot;no_create&quot;: True}"/>\n                    </div>\n                </group>\n                <footer>\n                    <button string="Update address and re-send" type="object" name="update_address_save" class="btn-primary" data-hotkey="q"/>\n                    <button string="Cancel letter" type="object" name="update_address_cancel" class="btn-secondary" data-hotkey="w"/>\n                    <button string="Close" special="cancel" class="btn-secondary" data-hotkey="x"/>\n                </footer>\n            </form>\n        	f	t	2026-09-17 06:40:20.357336	2026-09-17 06:40:20.357336	f
592	16	559	1	1	TOTP Portal hook	\N	auth_totp_portal.totp_portal_hook	qweb	auth_totp_portal/views/templates.xml	extension	{"en_US": "<data name=\\"TOTP Portal hook\\" inherit_id=\\"portal.portal_my_security\\">\\n        <xpath expr=\\"//section[@name='portal_change_password']\\" position=\\"after\\">\\n            <!--\\n                portal users don't have access to non-qweb views anymore, so\\n                embed the target view as a *data island* of sorts, a JSON embed\\n                of the fields_view_get could have been nice but at 14k it'd be a\\n                bit ridiculous\\n            -->\\n            <div class=\\"d-none\\" id=\\"totp_wizard_view\\">\\n                <t t-esc=\\"env.ref('auth_totp.view_totp_wizard').sudo().get_combined_arch()\\"/>\\n            </div>\\n            <section>\\n                <h4>\\n                    Two-factor authentication\\n                    <a href=\\"https://www.odoo.com/documentation/17.0/applications/general/auth/2fa.html\\" target=\\"_blank\\">\\n                        <i title=\\"Documentation\\" class=\\"fa fa-fw o_button_icon fa-info-circle\\"/>\\n                    </a>\\n                </h4>\\n                <t t-if=\\"not user_id.totp_enabled\\">\\n                    <div class=\\"alert alert-secondary\\" role=\\"status\\">\\n                        <i class=\\"fa fa-warning\\"/>\\n                        Two-factor authentication not enabled\\n                    </div>\\n                    <button type=\\"button\\" class=\\"btn btn-secondary\\" id=\\"auth_totp_portal_enable\\">\\n                        Enable two-factor authentication\\n                    </button>\\n                </t>\\n                <t t-else=\\"\\">\\n                    <span class=\\"text-success\\">\\n                        <i class=\\"fa fa-check-circle\\"/>\\n                        Two-factor authentication enabled\\n                    </span>\\n                    <button type=\\"button\\" class=\\"btn btn-link\\" id=\\"auth_totp_portal_disable\\">\\n                        (Disable two-factor authentication)\\n                    </button>\\n                    <t t-if=\\"len(user_id.totp_trusted_device_ids)\\">\\n                        <table class=\\"table o_main_table\\">\\n                            <thead>\\n                                <tr>\\n                                    <th><strong>Trusted Device</strong></th>\\n                                    <th><strong>Added On</strong></th>\\n                                </tr>\\n                            </thead>\\n                            <tbody>\\n                                <tr t-foreach=\\"user_id.totp_trusted_device_ids\\" t-as=\\"td\\">\\n                                    <td>\\n                                        <span t-field=\\"td.name\\"/>\\n                                    </td>\\n                                    <td>\\n                                        <span t-field=\\"td.create_date\\"/>\\n                                    </td>\\n                                    <td>\\n                                        <i class=\\"fa fa-trash text-danger\\" type=\\"button\\" t-att-id=\\"td.id\\"/>\\n                                    </td>\\n                                </tr>\\n                            </tbody>\\n                        </table>\\n                        <button class=\\"btn btn-primary\\" type=\\"button\\" id=\\"auth_totp_portal_revoke_all_devices\\">\\n                            Revoke All\\n                        </button>\\n                    </t>\\n                </t>\\n            </section>\\n        </xpath>\\n    </data>"}	<?xml version="1.0"?>\n<data name="TOTP Portal hook" inherit_id="portal.portal_my_security">\n        <xpath expr="//section[@name='portal_change_password']" position="after">\n            <!--\n                portal users don't have access to non-qweb views anymore, so\n                embed the target view as a *data island* of sorts, a JSON embed\n                of the fields_view_get could have been nice but at 14k it'd be a\n                bit ridiculous\n            -->\n            <div class="d-none" id="totp_wizard_view">\n                <t t-esc="env.ref('auth_totp.view_totp_wizard').sudo().get_combined_arch()"/>\n            </div>\n            <section>\n                <h4>\n                    Two-factor authentication\n                    <a href="https://www.odoo.com/documentation/17.0/applications/general/auth/2fa.html" target="_blank">\n                        <i title="Documentation" class="fa fa-fw o_button_icon fa-info-circle"/>\n                    </a>\n                </h4>\n                <t t-if="not user_id.totp_enabled">\n                    <div class="alert alert-secondary" role="status">\n                        <i class="fa fa-warning"/>\n                        Two-factor authentication not enabled\n                    </div>\n                    <button type="button" class="btn btn-secondary" id="auth_totp_portal_enable">\n                        Enable two-factor authentication\n                    </button>\n                </t>\n                <t t-else="">\n                    <span class="text-success">\n                        <i class="fa fa-check-circle"/>\n                        Two-factor authentication enabled\n                    </span>\n                    <button type="button" class="btn btn-link" id="auth_totp_portal_disable">\n                        (Disable two-factor authentication)\n                    </button>\n                    <t t-if="len(user_id.totp_trusted_device_ids)">\n                        <table class="table o_main_table">\n                            <thead>\n                                <tr>\n                                    <th><strong>Trusted Device</strong></th>\n                                    <th><strong>Added On</strong></th>\n                                </tr>\n        