678	16	\N	1	1	account.move.form	account.move	\N	form	account/views/account_move_views.xml	primary	{"en_US": "<form string=\\"Account Entry\\" js_class=\\"account_move_form\\">\\n                    <header>\\n                        <!-- Post -->\\n                        <button name=\\"action_post\\" string=\\"Post\\" class=\\"oe_highlight\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" data-hotkey=\\"q\\" context=\\"{'validate_analytic': True}\\" invisible=\\"hide_post_button or move_type != 'entry'\\"/>\\n                        <button name=\\"action_post\\" string=\\"Confirm\\" class=\\"oe_highlight\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" data-hotkey=\\"q\\" context=\\"{'validate_analytic': True}\\" invisible=\\"hide_post_button or move_type == 'entry' or display_inactive_currency_warning\\"/>\\n                        <!-- Send (only invoices) -->\\n                        <button name=\\"action_invoice_sent\\" type=\\"object\\" string=\\"Send &amp; Print\\" invisible=\\"state != 'posted' or is_being_sent or invoice_pdf_report_id or move_type not in ('out_invoice', 'out_refund')\\" class=\\"oe_highlight\\" data-hotkey=\\"y\\"/>\\n                        <button name=\\"action_invoice_sent\\" type=\\"object\\" string=\\"Send &amp; Print\\" invisible=\\"state != 'posted' or not is_being_sent and not invoice_pdf_report_id or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund')\\" data-hotkey=\\"y\\"/>\\n                        <!-- Register Payment (only invoices / receipts) -->\\n                        <button name=\\"action_register_payment\\" id=\\"account_invoice_payment_btn\\" type=\\"object\\" class=\\"oe_highlight\\" invisible=\\"state != 'posted' or payment_state not in ('not_paid', 'partial') or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\" context=\\"{'dont_redirect_to_payments': True, 'display_account_trust': True}\\" string=\\"Register Payment\\" data-hotkey=\\"g\\" groups=\\"account.group_account_invoice\\"/>\\n                        <!-- Preview (only customer invoices) -->\\n                        <button name=\\"preview_invoice\\" type=\\"object\\" string=\\"Preview\\" data-hotkey=\\"o\\" title=\\"Preview invoice\\" invisible=\\"move_type not in ('out_invoice', 'out_refund') or state == 'cancel'\\"/>\\n                        <!-- Reverse -->\\n                        <button name=\\"244\\" string=\\"Reverse Entry\\" type=\\"action\\" groups=\\"account.group_account_invoice\\" data-hotkey=\\"z\\" invisible=\\"move_type != 'entry' or state != 'posted' or payment_state == 'reversed'\\"/>\\n                        <button name=\\"action_reverse\\" string=\\"Credit Note\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" invisible=\\"move_type not in ('out_invoice', 'in_invoice') or state != 'posted'\\"/>\\n                        <!-- Cancel -->\\n                        <button name=\\"button_cancel\\" string=\\"Cancel Entry\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" data-hotkey=\\"x\\" invisible=\\"not id or state != 'draft' or move_type != 'entry'\\"/>\\n                        <button name=\\"button_cancel\\" string=\\"Cancel\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" data-hotkey=\\"x\\" invisible=\\"not id or state != 'draft' or move_type == 'entry'\\"/>\\n                        <button name=\\"button_draft\\" string=\\"Reset to Draft\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" invisible=\\"not show_reset_to_draft_button\\" data-hotkey=\\"r\\"/>\\n                        <button string=\\"Request Cancel\\" name=\\"button_request_cancel\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" invisible=\\"state != 'posted' or show_reset_to_draft_button or not need_cancel_request\\" data-hotkey=\\"w\\"/>\\n\\n                        <!-- Set as Checked -->\\n                        <button name=\\"button_set_checked\\" string=\\"Set as Checked\\" type=\\"object\\" groups=\\"account.group_account_invoice\\" invisible=\\"not to_check\\" data-hotkey=\\"k\\"/>\\n                        <field name=\\"state\\" widget=\\"statusbar\\" statusbar_visible=\\"draft,posted\\"/>\\n                    </header>\\n                    <div class=\\"alert alert-warning\\" role=\\"alert\\" invisible=\\"state != 'draft' or not duplicated_ref_ids\\">\\n                        Warning: this bill might be a duplicate of\\n                        <button name=\\"open_duplicated_ref_bill_view\\" type=\\"object\\" string=\\"one of those bills\\" class=\\"btn btn-link p-0\\"/>\\n                    </div>\\n                    <div class=\\"alert alert-info\\" role=\\"alert\\" invisible=\\"not is_being_sent\\">\\n                        This invoice is being sent in the background.\\n                    </div>\\n                    <!-- Invoice outstanding credits -->\\n                    <div groups=\\"account.group_account_invoice,account.group_account_readonly\\" class=\\"alert alert-warning\\" role=\\"alert\\" invisible=\\"state != 'draft' or not tax_lock_date_message\\">\\n                        <field name=\\"tax_lock_date_message\\" nolabel=\\"1\\"/>\\n                    </div>\\n                    <div groups=\\"account.group_account_invoice,account.group_account_readonly\\" class=\\"alert alert-info\\" role=\\"alert\\" invisible=\\"move_type not in ('out_invoice', 'out_receipt') or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')\\">\\n                        You have <bold><a class=\\"alert-link\\" href=\\"#outstanding\\" role=\\"button\\">outstanding credits</a></bold> for this customer. You can allocate them to mark this invoice as paid.\\n                    </div>\\n                    <div groups=\\"account.group_account_invoice,account.group_account_readonly\\" class=\\"alert alert-info\\" role=\\"alert\\" invisible=\\"move_type not in ('in_invoice', 'in_receipt') or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')\\">\\n                        You have <bold><a class=\\"alert-link\\" href=\\"#outstanding\\" role=\\"button\\">outstanding debits</a></bold> for this vendor. You can allocate them to mark this bill as paid.\\n                    </div>\\n                    <div groups=\\"account.group_account_invoice,account.group_account_readonly\\" class=\\"alert alert-info\\" role=\\"alert\\" invisible=\\"move_type != 'out_refund' or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')\\">\\n                        You have <bold><a class=\\"alert-link\\" href=\\"#outstanding\\" role=\\"button\\">outstanding debits</a></bold> for this customer. You can allocate them to mark this credit note as paid.\\n                    </div>\\n                    <div groups=\\"account.group_account_invoice,account.group_account_readonly\\" class=\\"alert alert-info\\" role=\\"alert\\" invisible=\\"move_type != 'in_refund' or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')\\">\\n                        You have <bold><a class=\\"alert-link\\" href=\\"#outstanding\\" role=\\"button\\">outstanding credits</a></bold> for this vendor. You can allocate them to mark this credit note as paid.\\n                    </div>\\n                    <div class=\\"alert alert-info\\" role=\\"alert\\" invisible=\\"state != 'draft' or auto_post != 'at_date'\\">\\n                        This move is configured to be posted automatically at the accounting date: <field name=\\"date\\" readonly=\\"1\\"/>.\\n                    </div>\\n                    <div class=\\"alert alert-info\\" role=\\"alert\\" invisible=\\"state != 'draft' or auto_post == 'no' or auto_post == 'at_date'\\">\\n                         <field name=\\"auto_post\\" readonly=\\"1\\"/> auto-posting enabled. Next accounting date: <field name=\\"date\\" readonly=\\"1\\"/>.<span invisible=\\"not auto_post_until\\"> The recurrence will end on <field name=\\"auto_post_until\\" readonly=\\"1\\"/> (included).</span>\\n                    </div>\\n                    <div groups=\\"account.group_account_invoice,account.group_account_readonly\\" class=\\"alert alert-warning\\" role=\\"alert\\" invisible=\\"partner_credit_warning == ''\\">\\n                        <field name=\\"partner_credit_warning\\"/>\\n                    </div>\\n                    <!-- Currency consistency -->\\n                    <div class=\\"alert alert-warning\\" role=\\"alert\\" invisible=\\"not display_inactive_currency_warning or move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\">\\n                        In order to validate this bill, you must <button class=\\"oe_link\\" type=\\"object\\" name=\\"action_activate_currency\\" style=\\"padding: 0; vertical-align: baseline;\\">activate the currency of the bill</button>. The journal entries need to be computed by Odoo before being posted in your company's currency.\\n                    </div>\\n                    <div class=\\"alert alert-warning\\" role=\\"alert\\" invisible=\\"not display_inactive_currency_warning or move_type not in ('out_invoice', 'out_refund', 'out_receipt')\\">\\n                        In order to validate this invoice, you must <button class=\\"oe_link\\" type=\\"object\\" name=\\"action_activate_currency\\" style=\\"padding: 0; vertical-align: baseline;\\">activate the currency of the invoice</button>. The journal entries need to be computed by Odoo before being posted in your company's currency.\\n                    </div>\\n                    <sheet>\\n                        <div name=\\"button_box\\" class=\\"oe_button_box\\">\\n                            <button name=\\"action_open_business_doc\\" class=\\"oe_stat_button\\" icon=\\"fa-bars\\" type=\\"object\\" invisible=\\"move_type != 'entry' or not id or not payment_id\\">\\n                                    <div class=\\"o_stat_info\\">\\n                                        <span class=\\"o_stat_text\\">1 Payment</span>\\n                                    </div>\\n                            </button>\\n                            <button name=\\"open_reconcile_view\\" class=\\"oe_stat_button\\" icon=\\"fa-bars\\" type=\\"object\\" invisible=\\"move_type != 'entry' or not id or not has_reconciled_entries\\">\\n                                    <div class=\\"o_stat_info\\">\\n                                        <span class=\\"o_stat_text\\">Reconciled Items</span>\\n                                    </div>\\n                            </button>\\n                            <button name=\\"open_created_caba_entries\\" class=\\"oe_stat_button\\" icon=\\"fa-usd\\" type=\\"object\\" invisible=\\"not tax_cash_basis_created_move_ids\\">\\n                                    <div class=\\"o_stat_info\\">\\n                                        <span class=\\"o_stat_text\\">Cash Basis Entries</span>\\n                                    </div>\\n                            </button>\\n                        </div>\\n\\n                        <!-- Payment status for invoices / receipts -->\\n                        <widget name=\\"web_ribbon\\" title=\\"Paid\\" invisible=\\"payment_state != 'paid' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\"/>\\n                        <widget name=\\"web_ribbon\\" title=\\"In Payment\\" invisible=\\"payment_state != 'in_payment' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\"/>\\n                        <widget name=\\"web_ribbon\\" title=\\"Partial\\" invisible=\\"payment_state != 'partial' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\"/>\\n                        <widget name=\\"web_ribbon\\" title=\\"Reversed\\" bg_color=\\"text-bg-danger\\" invisible=\\"payment_state != 'reversed'\\"/>\\n                         <widget name=\\"web_ribbon\\" text=\\"Invoicing App Legacy\\" bg_color=\\"text-bg-info\\" invisible=\\"payment_state != 'invoicing_legacy'\\" tooltip=\\"This entry has been generated through the Invoicing app, before installing Accounting. It has been disabled by the 'Invoicing Switch Threshold Date' setting so that it does not impact your accounting.\\"/>\\n\\n                        <!-- Invisible fields -->\\n                        <field name=\\"id\\" invisible=\\"1\\"/>\\n                        <field name=\\"state\\" invisible=\\"1\\"/>\\n                        <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"journal_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"show_name_warning\\" invisible=\\"1\\"/>\\n                        <field name=\\"posted_before\\" invisible=\\"1\\"/>\\n                        <!--test-tags .test_01_account_tour -->\\n                        <field name=\\"move_type\\" invisible=\\"1\\" force_save=\\"1\\"/>\\n                        <field name=\\"payment_state\\" invisible=\\"1\\" force_save=\\"1\\"/>\\n                        <field name=\\"invoice_filter_type_domain\\" invisible=\\"1\\"/>\\n                        <field name=\\"suitable_journal_ids\\" invisible=\\"1\\"/>\\n                        <field name=\\"currency_id\\" invisible=\\"1\\" readonly=\\"state in ['cancel', 'posted']\\"/>\\n                        <field name=\\"company_currency_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"commercial_partner_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"bank_partner_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"display_qr_code\\" invisible=\\"1\\"/>\\n                        <field name=\\"show_reset_to_draft_button\\" invisible=\\"1\\"/>\\n\\n                        <field name=\\"invoice_has_outstanding\\" invisible=\\"1\\"/>\\n                        <field name=\\"is_move_sent\\" invisible=\\"1\\"/>\\n                        <field name=\\"invoice_pdf_report_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"need_cancel_request\\" invisible=\\"1\\"/>\\n                        <field name=\\"has_reconciled_entries\\" invisible=\\"1\\"/>\\n                        <field name=\\"restrict_mode_hash_table\\" invisible=\\"1\\"/>\\n                        <field name=\\"inalterable_hash\\" invisible=\\"1\\"/>\\n                        <field name=\\"country_code\\" invisible=\\"1\\"/>\\n                        <field name=\\"display_inactive_currency_warning\\" invisible=\\"1\\"/>\\n                        <field name=\\"statement_line_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"statement_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"payment_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"tax_country_id\\" invisible=\\"1\\"/>\\n                        <field name=\\"tax_calculation_rounding_method\\" invisible=\\"1\\"/>\\n                        <field name=\\"tax_cash_basis_created_move_ids\\" invisible=\\"1\\"/>\\n                        <field name=\\"quick_edit_mode\\" invisible=\\"1\\"/>\\n                        <field name=\\"hide_post_button\\" invisible=\\"1\\"/>\\n                        <field name=\\"duplicated_ref_ids\\" invisible=\\"1\\"/>\\n                        <field name=\\"quick_encoding_vals\\" invisible=\\"1\\"/>\\n                        <field name=\\"show_delivery_date\\" invisible=\\"1\\"/>\\n                        <field name=\\"is_being_sent\\" invisible=\\"1\\"/>\\n                        <field name=\\"show_update_fpos\\" invisible=\\"1\\"/>\\n\\n                        <div class=\\"oe_title\\">\\n                            <span class=\\"o_form_label\\"><field name=\\"move_type\\" readonly=\\"1\\" invisible=\\"move_type == 'entry'\\" nolabel=\\"1\\"/></span>\\n\\n                            <div class=\\"text-warning\\" invisible=\\"not show_name_warning\\">The current highest number is <field class=\\"oe_inline\\" name=\\"highest_name\\"/>. You might want to put a higher number here.</div>\\n\\n                            <h1>\\n                                <field name=\\"name\\" invisible=\\"name == '/' and not posted_before and not quick_edit_mode\\" readonly=\\"state != 'draft'\\" placeholder=\\"Draft\\"/>\\n\\n                                <span invisible=\\"state != 'draft' or name != '/' or posted_before or quick_edit_mode\\">Draft</span>\\n                            </h1>\\n                        </div>\\n                        <group>\\n                            <group id=\\"header_left_group\\">\\n\\n                                <label for=\\"partner_id\\" string=\\"Customer\\" style=\\"font-weight:bold;\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'out_receipt')\\"/>\\n                                <label for=\\"partner_id\\" string=\\"Vendor\\" style=\\"font-weight:bold;\\" invisible=\\"move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\"/>\\n                                <div class=\\"o_col\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'out_receipt', 'in_invoice', 'in_refund', 'in_receipt')\\">\\n                                    <field name=\\"partner_id\\" widget=\\"res_partner_many2one\\" nolabel=\\"1\\" context=\\"{                                             'res_partner_search_mode': (context.get('default_move_type', 'entry') in ('out_invoice', 'out_refund', 'out_receipt') and 'customer') or (context.get('default_move_type', 'entry') in ('in_invoice', 'in_refund', 'in_receipt') and 'supplier') or False,                                             'show_address': 1, 'default_is_company': True, 'show_vat': True}\\" options=\\"{&quot;no_quick_create&quot;: True}\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\" readonly=\\"state != 'draft'\\"/>\\n                                    <button name=\\"action_update_fpos_values\\" type=\\"object\\" string=\\"Update Taxes and Accounts\\" help=\\"Recompute all taxes and accounts based on this fiscal position\\" class=\\"btn-link mb-1 px-0\\" icon=\\"fa-refresh\\" confirm=\\"This will update all taxes and accounts based on the currently selected fiscal position.\\" invisible=\\"not show_update_fpos or state in ['cancel', 'posted']\\"/>\\n                                </div>\\n\\n                                <field name=\\"partner_shipping_id\\" groups=\\"account.group_delivery_invoice_address\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'out_receipt')\\" readonly=\\"state != 'draft'\\"/>\\n                                <field name=\\"quick_edit_total_amount\\" class=\\"w-50\\" invisible=\\"move_type == 'entry' or not quick_edit_mode\\" readonly=\\"state != 'draft'\\"/>\\n                                <label for=\\"ref\\" string=\\"Bill Reference\\" invisible=\\"move_type not in ('in_invoice', 'in_receipt', 'in_refund')\\"/>\\n                                <field name=\\"ref\\" nolabel=\\"1\\" invisible=\\"move_type not in ('in_invoice', 'in_receipt', 'in_refund')\\"/>\\n                                <field name=\\"ref\\" invisible=\\"move_type in ('in_invoice', 'in_receipt', 'in_refund', 'out_invoice', 'out_refund')\\"/>\\n                                <field name=\\"tax_cash_basis_origin_move_id\\" invisible=\\"not tax_cash_basis_origin_move_id\\"/>\\n                                <label name=\\"invoice_vendor_bill_id_label\\" for=\\"invoice_vendor_bill_id\\" string=\\"Auto-Complete\\" class=\\"oe_edit_only\\" invisible=\\"state != 'draft' or move_type != 'in_invoice'\\"/>\\n                                <field name=\\"invoice_vendor_bill_id\\" nolabel=\\"1\\" class=\\"oe_edit_only\\" invisible=\\"state != 'draft' or move_type != 'in_invoice'\\" domain=\\"[('company_id', '=', company_id), ('partner_id','child_of', [partner_id]), ('move_type','=','in_invoice')]\\" placeholder=\\"Select an old vendor bill\\" options=\\"{'no_create': True}\\" context=\\"{'show_total_amount': True}\\"/>\\n                            </group>\\n                            <group id=\\"header_right_group\\">\\n\\n                                <!-- Invoice date (only invoices / receipts) -->\\n                                <label for=\\"invoice_date\\" string=\\"Invoice Date\\" style=\\"font-weight:bold;\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'out_receipt')\\"/>\\n                                <label for=\\"invoice_date\\" string=\\"Bill Date\\" style=\\"font-weight:bold;\\" invisible=\\"move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\"/>\\n                                <field name=\\"invoice_date\\" nolabel=\\"1\\" options=\\"{'warn_future': true}\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\" readonly=\\"state != 'draft'\\"/>\\n\\n                                <field name=\\"date\\" string=\\"Accounting Date\\" invisible=\\"move_type in ('out_invoice', 'out_refund', 'out_receipt') and not quick_edit_mode and not (state == 'posted' and date != invoice_date)\\" readonly=\\"state != 'draft'\\"/>\\n                                <field name=\\"payment_reference\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\" readonly=\\"inalterable_hash != False\\"/>\\n                                <field name=\\"partner_bank_id\\" context=\\"{'default_partner_id': bank_partner_id, 'display_account_trust': True}\\" domain=\\"[('partner_id', '=', bank_partner_id)]\\" invisible=\\"move_type not in ('in_invoice', 'in_refund', 'in_receipt')\\" readonly=\\"state != 'draft'\\"/>\\n\\n                                <!-- Invoice payment terms (only invoices) + due date (only invoices / receipts) -->\\n                                <div class=\\"o_td_label\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\">\\n                                    <label for=\\"invoice_date_due\\" string=\\"Due Date\\" invisible=\\"invoice_payment_term_id\\"/>\\n                                    <label for=\\"invoice_payment_term_id\\" string=\\"Payment terms\\" invisible=\\"not invoice_payment_term_id\\"/>\\n                                </div>\\n                                <div class=\\"d-flex\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')\\" name=\\"due_date\\">\\n                                    <field name=\\"invoice_date_due\\" force_save=\\"1\\" placeholder=\\"Date\\" invisible=\\"invoice_payment_term_id\\"/>\\n                                    <span class=\\"o_form_label mx-3 oe_edit_only\\" invisible=\\"state != 'draft' or invoice_payment_term_id\\"> or </span>\\n                                    <field name=\\"invoice_payment_term_id\\" context=\\"{'example_date': invoice_date, 'example_amount': tax_totals['amount_total']}\\" placeholder=\\"Payment Terms\\" options=\\"{'no_quick_create':True}\\" readonly=\\"state in ['cancel', 'posted']\\"/>\\n                                </div>\\n                                <field name=\\"delivery_date\\" invisible=\\"not show_delivery_date\\" readonly=\\"state != 'draft'\\"/>\\n                                <label for=\\"journal_id\\" groups=\\"account.group_account_readonly\\" invisible=\\"context.get('default_journal_id') and context.get('move_type', 'entry') != 'entry'\\"/>\\n                                <div name=\\"journal_div\\" class=\\"d-flex\\" groups=\\"account.group_account_readonly\\" invisible=\\"context.get('default_journal_id') and context.get('move_type', 'entry') != 'entry'\\">\\n                                    <field name=\\"journal_id\\" options=\\"{'no_create': True, 'no_open': True}\\" readonly=\\"posted_before and name not in (False, '', '/')\\"/>\\n                                    <span class=\\"oe_inline o_form_label mx-3\\" groups=\\"base.group_multi_currency\\" invisible=\\"move_type == 'entry'\\"> in </span>\\n                                    <field name=\\"currency_id\\" groups=\\"base.group_multi_currency\\" invisible=\\"move_type == 'entry'\\" readonly=\\"state != 'draft'\\" options=\\"{'no_create': True}\\" context=\\"{'search_default_active': 1, 'search_default_inactive': 1}\\"/>\\n                                </div>\\n\\n                                <field name=\\"currency_id\\" readonly=\\"state != 'draft'\\" groups=\\"!account.group_account_readonly,base.group_multi_currency\\" options=\\"{'no_create': True}\\"/>\\n\\n                            </group>\\n                        </group>\\n                        <notebook>\\n                            <page id=\\"invoice_tab\\" name=\\"invoice_tab\\" string=\\"Invoice Lines\\" invisible=\\"move_type == 'entry'\\">\\n                                <field name=\\"invoice_line_ids\\" widget=\\"section_and_note_one2many\\" mode=\\"tree,kanban\\" context=\\"{                                            'default_move_type': context.get('default_move_type'),                                            'journal_id': journal_id,                                            'default_partner_id': commercial_partner_id,                                            'default_currency_id': currency_id or company_currency_id,                                            'default_display_type': 'product',                                            'quick_encoding_vals': quick_encoding_vals,                                        }\\" readonly=\\"state != 'draft'\\">\\n                                    <tree editable=\\"bottom\\" string=\\"Journal Items\\" default_order=\\"sequence, id\\">\\n                                        <control>\\n                                            <create name=\\"add_line_control\\" string=\\"Add a line\\"/>\\n                                            <create name=\\"add_section_control\\" string=\\"Add a section\\" context=\\"{'default_display_type': 'line_section'}\\"/>\\n                                            <create name=\\"add_note_control\\" string=\\"Add a note\\" context=\\"{'default_display_type': 'line_note'}\\"/>\\n                                        </control>\\n\\n                                        <!-- Displayed fields -->\\n                                        <field name=\\"sequence\\" widget=\\"handle\\"/>\\n                                        <field name=\\"product_id\\" optional=\\"show\\" widget=\\"many2one_barcode\\" domain=\\"                                                     context.get('default_move_type') in ('out_invoice', 'out_refund', 'out_receipt')                                                     and [('sale_ok', '=', True)]                                                     or [('purchase_ok', '=', True)]                                                \\"/>\\n                                        <field name=\\"name\\" widget=\\"section_and_note_text\\" optional=\\"show\\"/>\\n                                        <field name=\\"account_id\\" context=\\"{'partner_id': partner_id, 'move_type': parent.move_type}\\" groups=\\"account.group_account_readonly\\" options=\\"{'no_quick_create': True}\\" domain=\\"[('deprecated', '=', False), ('account_type', 'not in', ('asset_receivable', 'liability_payable', 'off_balance')), ('company_id', 'parent_of', parent.company_id)]\\" required=\\"display_type not in ('line_note', 'line_section')\\"/>\\n                                        <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" groups=\\"analytic.group_analytic_accounting\\" optional=\\"show\\" options=\\"{'product_field': 'product_id', 'account_field': 'account_id', 'amount_field': 'price_subtotal'}\\" business_domain_compute=\\"parent.move_type in ['out_invoice', 'out_refund', 'out_receipt'] and 'invoice' or parent.move_type in ['in_invoice', 'in_refund', 'in_receipt'] and 'bill' or 'general'\\"/>\\n                                        <field name=\\"quantity\\" optional=\\"show\\"/>\\n                                        <field name=\\"product_uom_category_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"product_uom_id\\" string=\\"UoM\\" groups=\\"uom.group_uom\\" optional=\\"show\\"/>\\n                                        <!-- /l10n_in_edi.test_edi_json -->\\n                                        <!-- required for @api.onchange('product_id') -->\\n                                        <field name=\\"product_uom_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"price_unit\\" string=\\"Price\\"/>\\n                                        <field name=\\"discount\\" string=\\"Disc.%\\" optional=\\"hide\\"/>\\n                                        <field name=\\"tax_ids\\" widget=\\"many2many_tags\\" domain=\\"[('type_tax_use', '=?', parent.invoice_filter_type_domain), ('company_id', 'parent_of', parent.company_id), ('country_id', '=', parent.tax_country_id)]\\" context=\\"{'append_type_to_tax_name': not parent.invoice_filter_type_domain, 'active_test': True}\\" options=\\"{'no_create': True}\\" optional=\\"show\\"/>\\n                                        <field name=\\"price_subtotal\\" string=\\"Tax excl.\\"/>\\n                                        <field name=\\"price_total\\" string=\\"Tax incl.\\" column_invisible=\\"parent.tax_calculation_rounding_method == 'round_globally'\\" optional=\\"hide\\"/>\\n\\n                                        <!-- Others fields -->\\n                                        <field name=\\"partner_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"currency_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"company_currency_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"display_type\\" force_save=\\"1\\" column_invisible=\\"True\\"/>\\n                                    </tree>\\n                                    <kanban class=\\"o_kanban_mobile\\">\\n                                        <!-- Displayed fields -->\\n                                        <field name=\\"name\\"/>\\n                                        <field name=\\"product_id\\"/>\\n                                        <field name=\\"price_subtotal\\" string=\\"Tax excl.\\"/>\\n                                        <field name=\\"price_total\\" string=\\"Tax incl.\\" optional=\\"hide\\"/>\\n                                        <field name=\\"quantity\\"/>\\n                                        <field name=\\"product_uom_category_id\\"/>\\n                                        <field name=\\"product_uom_id\\" groups=\\"uom.group_uom\\"/>\\n                                        <field name=\\"price_unit\\"/>\\n                                        <templates>\\n                                            <t t-name=\\"kanban-box\\">\\n                                                <div t-attf-class=\\"oe_kanban_card oe_kanban_global_click ps-0 pe-0 {{ record.display_type.raw_value ? 'o_is_' + record.display_type.raw_value : '' }}\\">\\n                                                    <t t-if=\\"!['line_note', 'line_section'].includes(record.display_type.raw_value)\\">\\n                                                        <div class=\\"row g-0\\">\\n                                                            <div t-if=\\"record.product_id.raw_value\\" class=\\"col-2 pe-3\\">\\n                                                                <img t-att-src=\\"kanban_image('product.product', 'image_128', record.product_id.raw_value)\\" t-att-title=\\"record.product_id.value\\" t-att-alt=\\"record.product_id.value\\" style=\\"max-width: 100%;\\"/>\\n                                                            </div>\\n                                                            <div t-att-class=\\"{'col-10': record.product_id.raw_value}\\">\\n                                                                <div class=\\"row\\">\\n                                                                    <div class=\\"col\\">\\n                                                                        <strong t-if=\\"record.product_id.raw_value\\" t-out=\\"record.product_id.value\\"/>\\n                                                                        <strong t-else=\\"\\" t-out=\\"record.name.value\\"/>\\n                                                                    </div>\\n                                                                    <div class=\\"col-auto\\">\\n                                                                        <strong class=\\"float-end text-end\\">\\n                                                                            <t t-out=\\"record.price_subtotal.value\\"/>\\n                                                                            <t t-out=\\"record.price_total.value\\" t-if=\\"tax_calculation_rounding_method == 'round_per_line'\\"/>\\n                                                                        </strong>\\n                                                                    </div>\\n                                                                </div>\\n                                                                <div class=\\"text-muted\\">\\n                                                                    Quantity:\\n                                                                    <t t-out=\\"record.quantity.value\\"/>\\n                                                                    <t t-out=\\"record.product_uom_id.value\\" groups=\\"uom.group_uom\\"/>\\n                                                                </div>\\n                                                                <div class=\\"text-muted\\">\\n                                                                    Unit Price:\\n                                                                    <t t-out=\\"record.price_unit.value\\"/>\\n                                                                </div>\\n                                                            </div>\\n                                                        </div>\\n                                                    </t>\\n                                                    <t t-if=\\"record.display_type.raw_value === 'line_section' || record.display_type.raw_value === 'line_note'\\">\\n                                                        <div class=\\"row\\">\\n                                                            <div class=\\"col-12\\">\\n                                                                <t t-out=\\"record.name.value\\"/>\\n                                                            </div>\\n                                                        </div>\\n                                                    </t>\\n                                                </div>\\n                                            </t>\\n                                        </templates>\\n\\n                                        <!-- Others fields -->\\n                                        <field name=\\"tax_calculation_rounding_method\\"/>\\n                                        <field name=\\"currency_id\\"/>\\n                                        <field name=\\"company_currency_id\\"/>\\n                                        <field name=\\"display_type\\" force_save=\\"1\\"/>\\n                                    </kanban>\\n\\n                                    <!-- Form view to cover mobile use -->\\n                                    <form>\\n                                        <sheet>\\n                                            <field name=\\"tax_calculation_rounding_method\\" invisible=\\"1\\"/>\\n                                            <field name=\\"display_type\\" invisible=\\"1\\"/>\\n                                            <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                                            <field name=\\"partner_id\\" invisible=\\"1\\"/>\\n                                            <group>\\n                                                <field name=\\"product_id\\" widget=\\"many2one_barcode\\"/>\\n                                                <field name=\\"quantity\\"/>\\n                                                <field name=\\"product_uom_category_id\\" invisible=\\"1\\"/>\\n                                                <field name=\\"product_uom_id\\" groups=\\"uom.group_uom\\"/>\\n                                                <field name=\\"price_unit\\"/>\\n                                                <field name=\\"discount\\" string=\\"Disc.%\\"/>\\n                                            </group>\\n                                            <group>\\n                                                <field name=\\"account_id\\" domain=\\"[('company_id', 'parent_of', company_id), ('deprecated', '=', False)]\\" options=\\"{'no_create': True}\\" context=\\"{'partner_id': partner_id, 'move_type': parent.move_type}\\"/>\\n                                                <field name=\\"tax_ids\\" widget=\\"many2many_tags\\"/>\\n                                                <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" groups=\\"analytic.group_analytic_accounting\\"/>\\n                                            </group>\\n                                            <label for=\\"name\\" string=\\"Description\\" invisible=\\"display_type in ('line_note', 'line_section')\\"/>\\n                                            <label for=\\"name\\" string=\\"Section\\" invisible=\\"display_type != 'line_section'\\"/>\\n                                            <label for=\\"name\\" string=\\"Note\\" invisible=\\"display_type != 'line_note'\\"/>\\n                                            <field name=\\"name\\" widget=\\"text\\"/>\\n                                            <group>\\n                                                <field name=\\"price_subtotal\\" string=\\"Tax excl.\\"/>\\n                                                <field name=\\"price_total\\" string=\\"Tax incl.\\" invisible=\\"tax_calculation_rounding_method == 'round_globally'\\" optional=\\"hide\\"/>\\n                                            </group>\\n                                        </sheet>\\n                                    </form>\\n                                </field>\\n                                <group col=\\"12\\" class=\\"oe_invoice_lines_tab\\">\\n                                    <group colspan=\\"8\\">\\n                                        <field name=\\"narration\\" placeholder=\\"Terms and Conditions\\" colspan=\\"2\\" nolabel=\\"1\\"/>\\n                                    </group>\\n                                    <!-- Totals (only invoices / receipts) -->\\n                                    <group colspan=\\"4\\">\\n                                        <group class=\\"oe_subtotal_footer\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') or payment_state == 'invoicing_legacy'\\">\\n\\n                                            <field name=\\"tax_totals\\" widget=\\"account-tax-totals-field\\" nolabel=\\"1\\" colspan=\\"2\\" readonly=\\"state != 'draft' or (move_type not in ('in_invoice', 'in_refund', 'in_receipt') and not quick_edit_mode)\\"/>\\n\\n                                            <field name=\\"invoice_payments_widget\\" colspan=\\"2\\" nolabel=\\"1\\" widget=\\"payment\\"/>\\n                                            <field name=\\"amount_residual\\" class=\\"oe_subtotal_footer_separator\\" invisible=\\"state == 'draft'\\"/>\\n                                        </group>\\n                                        <field name=\\"invoice_outstanding_credits_debits_widget\\" class=\\"oe_invoice_outstanding_credits_debits\\" colspan=\\"2\\" nolabel=\\"1\\" widget=\\"payment\\" invisible=\\"state != 'posted'\\"/>\\n                                    </group>\\n                                </group>\\n                            </page>\\n                            <page id=\\"aml_tab\\" string=\\"Journal Items\\" groups=\\"account.group_account_readonly\\" name=\\"aml_tab\\">\\n                                <field name=\\"line_ids\\" mode=\\"tree,kanban\\" context=\\"{                                            'default_move_type': context.get('default_move_type'),                                            'line_ids': line_ids,                                            'journal_id': journal_id,                                            'default_partner_id': commercial_partner_id,                                            'default_currency_id': currency_id or company_currency_id,                                            'kanban_view_ref': 'account.account_move_line_view_kanban_mobile',                                        }\\" invisible=\\"payment_state == 'invoicing_legacy' and move_type != 'entry'\\" readonly=\\"state != 'draft'\\">\\n                                    <tree editable=\\"bottom\\" string=\\"Journal Items\\" decoration-muted=\\"display_type in ('line_section', 'line_note')\\" default_order=\\"sequence, id\\">\\n                                        <!-- Displayed fields -->\\n                                        <field name=\\"account_id\\" invisible=\\"display_type in ('line_section', 'line_note')\\" required=\\"display_type not in ('line_section', 'line_note')\\" domain=\\"[('company_id', 'parent_of', parent.company_id), ('deprecated', '=', False)]\\"/>\\n                                        <field name=\\"partner_id\\" optional=\\"show\\" domain=\\"['|', ('parent_id', '=', False), ('is_company', '=', True)]\\" column_invisible=\\"parent.move_type != 'entry'\\"/>\\n                                        <field name=\\"name\\" widget=\\"section_and_note_text\\" optional=\\"show\\"/>\\n                                        <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" groups=\\"analytic.group_analytic_accounting\\" optional=\\"show\\" options=\\"{'account_field': 'account_id'}\\" business_domain_compute=\\"parent.move_type in ['out_invoice', 'out_refund', 'out_receipt'] and 'invoice' or parent.move_type in ['in_invoice', 'in_refund', 'in_receipt'] and 'bill' or 'general'\\"/>\\n                                        <field name=\\"date_maturity\\" optional=\\"hide\\" invisible=\\"display_type in ('line_section', 'line_note')\\" column_invisible=\\"context.get('view_no_maturity')\\"/>\\n                                        <field name=\\"amount_currency\\" groups=\\"base.group_multi_currency\\" optional=\\"hide\\"/>\\n                                        <field name=\\"currency_id\\" options=\\"{'no_create': True}\\" optional=\\"hide\\" groups=\\"base.group_multi_currency\\" column_invisible=\\"parent.move_type != 'entry'\\"/>\\n                                        <field name=\\"tax_ids\\" widget=\\"autosave_many2many_tags\\" optional=\\"hide\\" domain=\\"[('type_tax_use', '=?', parent.invoice_filter_type_domain)]\\" context=\\"{'append_type_to_tax_name': not parent.invoice_filter_type_domain, 'active_test': True}\\" options=\\"{'no_create': True}\\" force_save=\\"1\\" readonly=\\"display_type in ('line_section', 'line_note') or tax_line_id or (parent.move_type in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') and account_type in ('asset_receivable', 'liability_payable'))\\"/>\\n                                        <field name=\\"debit\\" sum=\\"Total Debit\\" invisible=\\"display_type in ('line_section', 'line_note')\\" readonly=\\"parent.move_type in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') and display_type in ('line_section', 'line_note', 'product')\\"/>\\n                                        <field name=\\"credit\\" sum=\\"Total Credit\\" invisible=\\"display_type in ('line_section', 'line_note')\\" readonly=\\"parent.move_type in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') and display_type in ('line_section', 'line_note', 'product')\\"/>\\n                                        <field name=\\"balance\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"discount_date\\" string=\\"Discount Date\\" optional=\\"hide\\"/>\\n                                        <field name=\\"discount_amount_currency\\" string=\\"Discount Amount\\" optional=\\"hide\\"/>\\n\\n                                        <field name=\\"tax_tag_ids\\" widget=\\"many2many_tags\\" string=\\"Tax Grids\\" optional=\\"show\\" options=\\"{'no_create': True}\\" domain=\\"[                                                     ('applicability', '=', 'taxes'),                                                     '|', ('country_id', '=', parent.tax_country_id),                                                     ('country_id', '=', False),                                                 ]\\"/>\\n\\n                                        <field name=\\"tax_tag_invert\\" readonly=\\"1\\" optional=\\"hide\\" groups=\\"base.group_no_one\\"/>\\n\\n                                        <!-- Buttons -->\\n                                        <button name=\\"action_automatic_entry\\" type=\\"object\\" icon=\\"fa-calendar\\" string=\\"Cut-Off\\" aria-label=\\"Change Period\\" class=\\"float-end\\" column_invisible=\\"parent.move_type == 'entry' or parent.state != 'posted'\\" invisible=\\"account_internal_group not in ('income', 'expense')\\" context=\\"{'default_action': 'change_period'}\\"/>\\n\\n                                        <!-- Others fields -->\\n                                        <field name=\\"tax_line_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"company_currency_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"display_type\\" force_save=\\"1\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"company_id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"sequence\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"id\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"account_internal_group\\" column_invisible=\\"True\\"/>\\n                                        <field name=\\"account_type\\" column_invisible=\\"True\\"/>\\n                                    </tree>\\n                                    <!-- Form view to cover mobile use -->\\n                                    <form>\\n                                      <group>\\n                                        <field name=\\"account_id\\" domain=\\"[('company_id', 'parent_of', parent.company_id), ('deprecated', '=', False)]\\"/>\\n                                        <field name=\\"partner_id\\" domain=\\"['|', ('parent_id', '=', False), ('is_company', '=', True)]\\"/>\\n                                        <field name=\\"name\\"/>\\n                                        <field name=\\"analytic_distribution\\" widget=\\"analytic_distribution\\" groups=\\"analytic.group_analytic_accounting\\"/>\\n                                        <field name=\\"amount_currency\\" groups=\\"base.group_multi_currency\\"/>\\n                                        <field name=\\"company_currency_id\\" invisible=\\"1\\"/>\\n                                        <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                                        <field name=\\"currency_id\\" options=\\"{'no_create': True}\\" groups=\\"base.group_multi_currency\\"/>\\n                                        <field name=\\"debit\\" sum=\\"Total Debit\\"/>\\n                                        <field name=\\"credit\\" sum=\\"Total Credit\\"/>\\n                                        <field name=\\"balance\\" invisible=\\"1\\"/>\\n                                        <field name=\\"tax_ids\\" string=\\"Taxes Applied\\" widget=\\"many2many_tags\\" options=\\"{'no_create': True}\\"/>\\n                                        <field name=\\"date_maturity\\" required=\\"0\\" invisible=\\"context.get('view_no_maturity', False)\\"/>\\n                                      </group>\\n                                    </form>\\n                                </field>\\n                                <div class=\\"alert alert-info text-center mb-0\\" role=\\"alert\\" invisible=\\"payment_state != 'invoicing_legacy' or move_type == 'entry'\\">\\n                                    <span>This entry has been generated through the Invoicing app, before installing Accounting. Its balance has been imported separately.</span>\\n                                </div>\\n                            </page>\\n                            <page id=\\"other_tab\\" string=\\"Other Info\\" name=\\"other_info\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund')\\">\\n                                <group id=\\"other_tab_group\\">\\n                                    <group string=\\"Invoice\\" name=\\"sale_info_group\\" invisible=\\"move_type not in ('out_invoice', 'out_refund')\\">\\n                                        <label for=\\"ref\\" string=\\"Customer Reference\\"/>\\n                                        <field name=\\"ref\\" nolabel=\\"1\\"/>\\n                                        <field name=\\"user_id\\" invisible=\\"1\\" force_save=\\"1\\"/>\\n                                        <field name=\\"invoice_user_id\\" domain=\\"[('share', '=', False)]\\" widget=\\"many2one_avatar_user\\"/>\\n                                        <field name=\\"invoice_origin\\" string=\\"Source Document\\" force_save=\\"1\\" invisible=\\"1\\"/>\\n                                        <field name=\\"partner_bank_id\\" context=\\"{'default_partner_id': bank_partner_id, 'display_account_trust': True}\\" domain=\\"[('partner_id.ref_company_ids', 'parent_of', company_id)]\\" invisible=\\"move_type != 'out_invoice'\\" readonly=\\"state != 'draft'\\"/>\\n                                        <field name=\\"partner_bank_id\\" context=\\"{'default_partner_id': bank_partner_id, 'display_account_trust': True}\\" domain=\\"[('partner_id', '=', bank_partner_id)]\\" invisible=\\"move_type != 'out_refund'\\" readonly=\\"state != 'draft'\\"/>\\n                                        <field name=\\"qr_code_method\\" invisible=\\"not display_qr_code\\"/>\\n                                        <field name=\\"delivery_date\\" readonly=\\"state != 'draft'\\"/>\\n                                    </group>\\n                                    <group string=\\"Accounting\\" name=\\"accounting_info_group\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund')\\">\\n                                        <field name=\\"company_id\\" groups=\\"base.group_multi_company\\"/>\\n                                        <field name=\\"invoice_incoterm_id\\"/>\\n                                        <field name=\\"incoterm_location\\"/>\\n                                        <field name=\\"fiscal_position_id\\" readonly=\\"state in ['cancel', 'posted']\\"/>\\n                                        <field name=\\"invoice_cash_rounding_id\\" groups=\\"account.group_cash_rounding\\" readonly=\\"state != 'draft'\\"/>\\n                                        <field name=\\"invoice_source_email\\" widget=\\"email\\" invisible=\\"move_type not in ('in_invoice', 'in_refund') or not invoice_source_email\\"/>\\n                                        <field name=\\"auto_post\\" readonly=\\"state != 'draft'\\"/>\\n                                        <field name=\\"auto_post_until\\" invisible=\\"auto_post in ('no', 'at_date')\\" readonly=\\"state != 'draft'\\"/>\\n                                        <field name=\\"to_check\\"/>\\n                                    </group>\\n                                </group>\\n                            </page>\\n                            <page id=\\"other_tab_entry\\" string=\\"Other Info\\" name=\\"other_info\\" invisible=\\"move_type != 'entry'\\">\\n                                <group id=\\"other_tab_entry_group\\">\\n                                    <group name=\\"misc_group\\">\\n                                        <field name=\\"auto_post\\" invisible=\\"move_type != 'entry'\\" readonly=\\"state != 'draft'\\"/>\\n                                        <field name=\\"reversed_entry_id\\" invisible=\\"move_type != 'entry' or not reversed_entry_id\\"/>\\n                                        <field name=\\"auto_post_until\\" invisible=\\"auto_post in ('no', 'at_date')\\" readonly=\\"state != 'draft'\\"/>\\n                                        <field name=\\"to_check\\" invisible=\\"move_type != 'entry'\\"/>\\n                                    </group>\\n                                    <group>\\n                                        <field name=\\"fiscal_position_id\\" readonly=\\"state in ['cancel', 'posted']\\"/>\\n                                        <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" required=\\"1\\"/>\\n                                    </group>\\n                                </group>\\n                                <!-- Internal note -->\\n                                <field name=\\"narration\\" placeholder=\\"Add an internal note...\\" nolabel=\\"1\\" height=\\"50\\"/>\\n                            </page>\\n                        </notebook>\\n                    </sheet>\\n                    <!-- Attachment preview -->\\n                    <div class=\\"o_attachment_preview\\" invisible=\\"move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund') or state != 'draft'\\"/>\\n                    <!-- Chatter -->\\n                    <div class=\\"oe_chatter\\">\\n                        <field name=\\"message_follower_ids\\" groups=\\"base.group_user\\"/>\\n                        <field name=\\"activity_ids\\"/>\\n                        <field name=\\"message_ids\\" options=\\"{'post_refresh': 'always'}\\"/>\\n                    </div>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Account Entry" js_class="account_move_form">\n                    <header>\n                        <!-- Post -->\n                        <button name="action_post" string="Post" class="oe_highlight" type="object" groups="account.group_account_invoice" data-hotkey="q" context="{'validate_analytic': True}" invisible="hide_post_button or move_type != 'entry'"/>\n                        <button name="action_post" string="Confirm" class="oe_highlight" type="object" groups="account.group_account_invoice" data-hotkey="q" context="{'validate_analytic': True}" invisible="hide_post_button or move_type == 'entry' or display_inactive_currency_warning"/>\n                        <!-- Send (only invoices) -->\n                        <button name="action_invoice_sent" type="object" string="Send &amp; Print" invisible="state != 'posted' or is_being_sent or invoice_pdf_report_id or move_type not in ('out_invoice', 'out_refund')" class="oe_highlight" data-hotkey="y"/>\n                        <button name="action_invoice_sent" type="object" string="Send &amp; Print" invisible="state != 'posted' or not is_being_sent and not invoice_pdf_report_id or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund')" data-hotkey="y"/>\n                        <!-- Register Payment (only invoices / receipts) -->\n                        <button name="action_register_payment" id="account_invoice_payment_btn" type="object" class="oe_highlight" invisible="state != 'posted' or payment_state not in ('not_paid', 'partial') or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')" context="{'dont_redirect_to_payments': True, 'display_account_trust': True}" string="Register Payment" data-hotkey="g" groups="account.group_account_invoice"/>\n                        <!-- Preview (only customer invoices) -->\n                        <button name="preview_invoice" type="object" string="Preview" data-hotkey="o" title="Preview invoice" invisible="move_type not in ('out_invoice', 'out_refund') or state == 'cancel'"/>\n                        <!-- Reverse -->\n                        <button name="244" string="Reverse Entry" type="action" groups="account.group_account_invoice" data-hotkey="z" invisible="move_type != 'entry' or state != 'posted' or payment_state == 'reversed'"/>\n                        <button name="action_reverse" string="Credit Note" type="object" groups="account.group_account_invoice" invisible="move_type not in ('out_invoice', 'in_invoice') or state != 'posted'"/>\n                        <!-- Cancel -->\n                        <button name="button_cancel" string="Cancel Entry" type="object" groups="account.group_account_invoice" data-hotkey="x" invisible="not id or state != 'draft' or move_type != 'entry'"/>\n                        <button name="button_cancel" string="Cancel" type="object" groups="account.group_account_invoice" data-hotkey="x" invisible="not id or state != 'draft' or move_type == 'entry'"/>\n                        <button name="button_draft" string="Reset to Draft" type="object" groups="account.group_account_invoice" invisible="not show_reset_to_draft_button" data-hotkey="r"/>\n                        <button string="Request Cancel" name="button_request_cancel" type="object" groups="account.group_account_invoice" invisible="state != 'posted' or show_reset_to_draft_button or not need_cancel_request" data-hotkey="w"/>\n\n                        <!-- Set as Checked -->\n                        <button name="button_set_checked" string="Set as Checked" type="object" groups="account.group_account_invoice" invisible="not to_check" data-hotkey="k"/>\n                        <field name="state" widget="statusbar" statusbar_visible="draft,posted"/>\n                    </header>\n                    <div class="alert alert-warning" role="alert" invisible="state != 'draft' or not duplicated_ref_ids">\n                        Warning: this bill might be a duplicate of\n                        <button name="open_duplicated_ref_bill_view" type="object" string="one of those bills" class="btn btn-link p-0"/>\n                    </div>\n                    <div class="alert alert-info" role="alert" invisible="not is_being_sent">\n                        This invoice is being sent in the background.\n                    </div>\n                    <!-- Invoice outstanding credits -->\n                    <div groups="account.group_account_invoice,account.group_account_readonly" class="alert alert-warning" role="alert" invisible="state != 'draft' or not tax_lock_date_message">\n                        <field name="tax_lock_date_message" nolabel="1"/>\n                    </div>\n                    <div groups="account.group_account_invoice,account.group_account_readonly" class="alert alert-info" role="alert" invisible="move_type not in ('out_invoice', 'out_receipt') or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')">\n                        You have <bold><a class="alert-link" href="#outstanding" role="button">outstanding credits</a></bold> for this customer. You can allocate them to mark this invoice as paid.\n                    </div>\n                    <div groups="account.group_account_invoice,account.group_account_readonly" class="alert alert-info" role="alert" invisible="move_type not in ('in_invoice', 'in_receipt') or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')">\n                        You have <bold><a class="alert-link" href="#outstanding" role="button">outstanding debits</a></bold> for this vendor. You can allocate them to mark this bill as paid.\n                    </div>\n                    <div groups="account.group_account_invoice,account.group_account_readonly" class="alert alert-info" role="alert" invisible="move_type != 'out_refund' or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')">\n                        You have <bold><a class="alert-link" href="#outstanding" role="button">outstanding debits</a></bold> for this customer. You can allocate them to mark this credit note as paid.\n                    </div>\n                    <div groups="account.group_account_invoice,account.group_account_readonly" class="alert alert-info" role="alert" invisible="move_type != 'in_refund' or not invoice_has_outstanding or payment_state not in ('not_paid', 'partial')">\n                        You have <bold><a class="alert-link" href="#outstanding" role="button">outstanding credits</a></bold> for this vendor. You can allocate them to mark this credit note as paid.\n                    </div>\n                    <div class="alert alert-info" role="alert" invisible="state != 'draft' or auto_post != 'at_date'">\n                        This move is configured to be posted automatically at the accounting date: <field name="date" readonly="1"/>.\n                    </div>\n                    <div class="alert alert-info" role="alert" invisible="state != 'draft' or auto_post == 'no' or auto_post == 'at_date'">\n                         <field name="auto_post" readonly="1"/> auto-posting enabled. Next accounting date: <field name="date" readonly="1"/>.<span invisible="not auto_post_until"> The recurrence will end on <field name="auto_post_until" readonly="1"/> (included).</span>\n                    </div>\n                    <div groups="account.group_account_invoice,account.group_account_readonly" class="alert alert-warning" role="alert" invisible="partner_credit_warning == ''">\n                        <field name="partner_credit_warning"/>\n                    </div>\n                    <!-- Currency consistency -->\n                    <div class="alert alert-warning" role="alert" invisible="not display_inactive_currency_warning or move_type not in ('in_invoice', 'in_refund', 'in_receipt')">\n                        In order to validate this bill, you must <button class="oe_link" type="object" name="action_activate_currency" style="padding: 0; vertical-align: baseline;">activate the currency of the bill</button>. The journal entries need to be computed by Odoo before being posted in your company's currency.\n                    </div>\n                    <div class="alert alert-warning" role="alert" invisible="not display_inactive_currency_warning or move_type not in ('out_invoice', 'out_refund', 'out_receipt')">\n                        In order to validate this invoice, you must <button class="oe_link" type="object" name="action_activate_currency" style="padding: 0; vertical-align: baseline;">activate the currency of the invoice</button>. The journal entries need to be computed by Odoo before being posted in your company's currency.\n                    </div>\n                    <sheet>\n                        <div name="button_box" class="oe_button_box">\n                            <button name="action_open_business_doc" class="oe_stat_button" icon="fa-bars" type="object" invisible="move_type != 'entry' or not id or not payment_id">\n                                    <div class="o_stat_info">\n                                        <span class="o_stat_text">1 Payment</span>\n                                    </div>\n                            </button>\n                            <button name="open_reconcile_view" class="oe_stat_button" icon="fa-bars" type="object" invisible="move_type != 'entry' or not id or not has_reconciled_entries">\n                                    <div class="o_stat_info">\n                                        <span class="o_stat_text">Reconciled Items</span>\n                                    </div>\n                            </button>\n                            <button name="open_created_caba_entries" class="oe_stat_button" icon="fa-usd" type="object" invisible="not tax_cash_basis_created_move_ids">\n                                    <div class="o_stat_info">\n                                        <span class="o_stat_text">Cash Basis Entries</span>\n                                    </div>\n                            </button>\n                        </div>\n\n                        <!-- Payment status for invoices / receipts -->\n                        <widget name="web_ribbon" title="Paid" invisible="payment_state != 'paid' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')"/>\n                        <widget name="web_ribbon" title="In Payment" invisible="payment_state != 'in_payment' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')"/>\n                        <widget name="web_ribbon" title="Partial" invisible="payment_state != 'partial' or move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')"/>\n                        <widget name="web_ribbon" title="Reversed" bg_color="text-bg-danger" invisible="payment_state != 'reversed'"/>\n                         <widget name="web_ribbon" text="Invoicing App Legacy" bg_color="text-bg-info" invisible="payment_state != 'invoicing_legacy'" tooltip="This entry has been generated through the Invoicing app, before installing Accounting. It has been disabled by the 'Invoicing Switch Threshold Date' setting so that it does not impact your accounting."/>\n\n                        <!-- Invisible fields -->\n                        <field name="id" invisible="1"/>\n                        <field name="state" invisible="1"/>\n                        <field name="company_id" invisible="1"/>\n                        <field name="journal_id" invisible="1"/>\n                        <field name="show_name_warning" invisible="1"/>\n                        <field name="posted_before" invisible="1"/>\n                        <!--test-tags .test_01_account_tour -->\n                        <field name="move_type" invisible="1" force_save="1"/>\n                        <field name="payment_state" invisible="1" force_save="1"/>\n                        <field name="invoice_filter_type_domain" invisible="1"/>\n                        <field name="suitable_journal_ids" invisible="1"/>\n                        <field name="currency_id" invisible="1" readonly="state in ['cancel', 'posted']"/>\n                        <field name="company_currency_id" invisible="1"/>\n                        <field name="commercial_partner_id" invisible="1"/>\n                        <field name="bank_partner_id" invisible="1"/>\n                        <field name="display_qr_code" invisible="1"/>\n                        <field name="show_reset_to_draft_button" invisible="1"/>\n\n                        <field name="invoice_has_outstanding" invisible="1"/>\n                        <field name="is_move_sent" invisible="1"/>\n                        <field name="invoice_pdf_report_id" invisible="1"/>\n                        <field name="need_cancel_request" invisible="1"/>\n                        <field name="has_reconciled_entries" invisible="1"/>\n                        <field name="restrict_mode_hash_table" invisible="1"/>\n                        <field name="inalterable_hash" invisible="1"/>\n                        <field name="country_code" invisible="1"/>\n                        <field name="display_inactive_currency_warning" invisible="1"/>\n                        <field name="statement_line_id" invisible="1"/>\n                        <field name="statement_id" invisible="1"/>\n                        <field name="payment_id" invisible="1"/>\n                        <field name="tax_country_id" invisible="1"/>\n                        <field name="tax_calculation_rounding_method" invisible="1"/>\n                        <field name="tax_cash_basis_created_move_ids" invisible="1"/>\n                        <field name="quick_edit_mode" invisible="1"/>\n                        <field name="hide_post_button" invisible="1"/>\n                        <field name="duplicated_ref_ids" invisible="1"/>\n                        <field name="quick_encoding_vals" invisible="1"/>\n                        <field name="show_delivery_date" invisible="1"/>\n                        <field name="is_being_sent" invisible="1"/>\n                        <field name="show_update_fpos" invisible="1"/>\n\n                        <div class="oe_title">\n                            <span class="o_form_label"><field name="move_type" readonly="1" invisible="move_type == 'entry'" nolabel="1"/></span>\n\n                            <div class="text-warning" invisible="not show_name_warning">The current highest number is <field class="oe_inline" name="highest_name"/>. You might want to put a higher number here.</div>\n\n                            <h1>\n                                <field name="name" invisible="name == '/' and not posted_before and not quick_edit_mode" readonly="state != 'draft'" placeholder="Draft"/>\n\n                                <span invisible="state != 'draft' or name != '/' or posted_before or quick_edit_mode">Draft</span>\n                            </h1>\n                        </div>\n                        <group>\n                            <group id="header_left_group">\n\n                                <label for="partner_id" string="Customer" style="font-weight:bold;" invisible="move_type not in ('out_invoice', 'out_refund', 'out_receipt')"/>\n                                <label for="partner_id" string="Vendor" style="font-weight:bold;" invisible="move_type not in ('in_invoice', 'in_refund', 'in_receipt')"/>\n                                <div class="o_col" invisible="move_type not in ('out_invoice', 'out_refund', 'out_receipt', 'in_invoice', 'in_refund', 'in_receipt')">\n                                    <field name="partner_id" widget="res_partner_many2one" nolabel="1" context="{                                             'res_partner_search_mode': (context.get('default_move_type', 'entry') in ('out_invoice', 'out_refund', 'out_receipt') and 'customer') or (context.get('default_move_type', 'entry') in ('in_invoice', 'in_refund', 'in_receipt') and 'supplier') or False,                                             'show_address': 1, 'default_is_company': True, 'show_vat': True}" options="{&quot;no_quick_create&quot;: True}" invisible="move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')" readonly="state != 'draft'"/>\n                                    <button name="action_update_fpos_values" type="object" string="Update Taxes and Accounts" help="Recompute all taxes and accounts based on this fiscal position" class="btn-link mb-1 px-0" icon="fa-refresh" confirm="This will update all taxes and accounts based on the currently selected fiscal position." invisible="not show_update_fpos or state in ['cancel', 'posted']"/>\n                                </div>\n\n                                <field name="partner_shipping_id" groups="account.group_delivery_invoice_address" invisible="move_type not in ('out_invoice', 'out_refund', 'out_receipt')" readonly="state != 'draft'"/>\n                                <field name="quick_edit_total_amount" class="w-50" invisible="move_type == 'entry' or not quick_edit_mode" readonly="state != 'draft'"/>\n                                <label for="ref" string="Bill Reference" invisible="move_type not in ('in_invoice', 'in_receipt', 'in_refund')"/>\n                                <field name="ref" nolabel="1" invisible="move_type not in ('in_invoice', 'in_receipt', 'in_refund')"/>\n                                <field name="ref" invisible="move_type in ('in_invoice', 'in_receipt', 'in_refund', 'out_invoice', 'out_refund')"/>\n                                <field name="tax_cash_basis_origin_move_id" invisible="not tax_cash_basis_origin_move_id"/>\n                                <label name="invoice_vendor_bill_id_label" for="invoice_vendor_bill_id" string="Auto-Complete" class="oe_edit_only" invisible="state != 'draft' or move_type != 'in_invoice'"/>\n                                <field name="invoice_vendor_bill_id" nolabel="1" class="oe_edit_only" invisible="state != 'draft' or move_type != 'in_invoice'" domain="[('company_id', '=', company_id), ('partner_id','child_of', [partner_id]), ('move_type','=','in_invoice')]" placeholder="Select an old vendor bill" options="{'no_create': True}" context="{'show_total_amount': True}"/>\n                            </group>\n                            <group id="header_right_group">\n\n                                <!-- Invoice date (only invoices / receipts) -->\n                                <label for="invoice_date" string="Invoice Date" style="font-weight:bold;" invisible="move_type not in ('out_invoice', 'out_refund', 'out_receipt')"/>\n                                <label for="invoice_date" string="Bill Date" style="font-weight:bold;" invisible="move_type not in ('in_invoice', 'in_refund', 'in_receipt')"/>\n                                <field name="invoice_date" nolabel="1" options="{'warn_future': true}" invisible="move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')" readonly="state != 'draft'"/>\n\n                                <field name="date" string="Accounting Date" invisible="move_type in ('out_invoice', 'out_refund', 'out_receipt') and not quick_edit_mode and not (state == 'posted' and date != invoice_date)" readonly="state != 'draft'"/>\n                                <field name="payment_reference" invisible="move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')" readonly="inalterable_hash != False"/>\n                                <field name="partner_bank_id" context="{'default_partner_id': bank_partner_id, 'display_account_trust': True}" domain="[('partner_id', '=', bank_partner_id)]" invisible="move_type not in ('in_invoice', 'in_refund', 'in_receipt')" readonly="state != 'draft'"/>\n\n                                <!-- Invoice payment terms (only invoices) + due date (only invoices / receipts) -->\n                                <div class="o_td_label" invisible="move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')">\n                                    <label for="invoice_date_due" string="Due Date" invisible="invoice_payment_term_id"/>\n                                    <label for="invoice_payment_term_id" string="Payment terms" invisible="not invoice_payment_term_id"/>\n                                </div>\n                                <div class="d-flex" invisible="move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt')" name="due_date">\n                                    <field name="invoice_date_due" force_save="1" placeholder="Date" invisible="invoice_payment_term_id"/>\n                                    <span class="o_form_label mx-3 oe_edit_only" invisible="state != 'draft' or invoice_payment_term_id"> or </span>\n                                    <field name="invoice_payment_term_id" context="{'example_date': invoice_date, 'example_amount': tax_totals['amount_total']}" placeholder="Payment Terms" options="{'no_quick_create':True}" readonly="state in ['cancel', 'posted']"/>\n                                </div>\n                                <field name="delivery_date" invisible="not show_delivery_date" readonly="state != 'draft'"/>\n                                <label for="journal_id" groups="account.group_account_readonly" invisible="context.get('default_journal_id') and context.get('move_type', 'entry') != 'entry'"/>\n                                <div name="journal_div" class="d-flex" groups="account.group_account_readonly" invisible="context.get('default_journal_id') and context.get('move_type', 'entry') != 'entry'">\n                                    <field name="journal_id" options="{'no_create': True, 'no_open': True}" readonly="posted_before and name not in (False, '', '/')"/>\n                                    <span class="oe_inline o_form_label mx-3" groups="base.group_multi_currency" invisible="move_type == 'entry'"> in </span>\n                                    <field name="currency_id" groups="base.group_multi_currency" invisible="move_type == 'entry'" readonly="state != 'draft'" options="{'no_create': True}" context="{'search_default_active': 1, 'search_default_inactive': 1}"/>\n                                </div>\n\n                                <field name="currency_id" readonly="state != 'draft'" groups="!account.group_account_readonly,base.group_multi_currency" options="{'no_create': True}"/>\n\n                            </group>\n                        </group>\n                        <notebook>\n                            <page id="invoice_tab" name="invoice_tab" string="Invoice Lines" invisible="move_type == 'entry'">\n                                <field name="invoice_line_ids" widget="section_and_note_one2many" mode="tree,kanban" context="{                                            'default_move_type': context.get('default_move_type'),                                            'journal_id': journal_id,                                            'default_partner_id': commercial_partner_id,                                            'default_currency_id': currency_id or company_currency_id,                                            'default_display_type': 'product',                                            'quick_encoding_vals': quick_encoding_vals,                                        }" readonly="state != 'draft'">\n                                    <tree editable="bottom" string="Journal Items" default_order="sequence, id">\n                                        <control>\n                                            <create name="add_line_control" string="Add a line"/>\n                                            <create name="add_section_control" string="Add a section" context="{'default_display_type': 'line_section'}"/>\n                                            <create name="add_note_control" string="Add a note" context="{'default_display_type': 'line_note'}"/>\n                                        </control>\n\n                                        <!-- Displayed fields -->\n                                        <field name="sequence" widget="handle"/>\n                                        <field name="product_id" optional="show" widget="many2one_barcode" domain="                                                     context.get('default_move_type') in ('out_invoice', 'out_refund', 'out_receipt')                                                     and [('sale_ok', '=', True)]                                                     or [('purchase_ok', '=', True)]                                                "/>\n                                        <field name="name" widget="section_and_note_text" optional="show"/>\n                                        <field name="account_id" context="{'partner_id': partner_id, 'move_type': parent.move_type}" groups="account.group_account_readonly" options="{'no_quick_create': True}" domain="[('deprecated', '=', False), ('account_type', 'not in', ('asset_receivable', 'liability_payable', 'off_balance')), ('company_id', 'parent_of', parent.company_id)]" required="display_type not in ('line_note', 'line_section')"/>\n                                        <field name="analytic_distribution" widget="analytic_distribution" groups="analytic.group_analytic_accounting" optional="show" options="{'product_field': 'product_id', 'account_field': 'account_id', 'amount_field': 'price_subtotal'}" business_domain_compute="parent.move_type in ['out_invoice', 'out_refund', 'out_receipt'] and 'invoice' or parent.move_type in ['in_invoice', 'in_refund', 'in_receipt'] and 'bill' or 'general'"/>\n                                        <field name="quantity" optional="show"/>\n                                        <field name="product_uom_category_id" column_invisible="True"/>\n                                        <field name="product_uom_id" string="UoM" groups="uom.group_uom" optional="show"/>\n                                        <!-- /l10n_in_edi.test_edi_json -->\n                                        <!-- required for @api.onchange('product_id') -->\n                                        <field name="product_uom_id" column_invisible="True"/>\n                                        <field name="price_unit" string="Price"/>\n                                        <field name="discount" string="Disc.%" optional="hide"/>\n                                        <field name="tax_ids" widget="many2many_tags" domain="[('type_tax_use', '=?', parent.invoice_filter_type_domain), ('company_id', 'parent_of', parent.company_id), ('country_id', '=', parent.tax_country_id)]" context="{'append_type_to_tax_name': not parent.invoice_filter_type_domain, 'active_test': True}" options="{'no_create': True}" optional="show"/>\n                                        <field name="price_subtotal" string="Tax excl."/>\n                                        <field name="price_total" string="Tax incl." column_invisible="parent.tax_calculation_rounding_method == 'round_globally'" optional="hide"/>\n\n                                        <!-- Others fields -->\n                                        <field name="partner_id" column_invisible="True"/>\n                                        <field name="currency_id" column_invisible="True"/>\n                                        <field name="company_id" column_invisible="True"/>\n                                        <field name="company_currency_id" column_invisible="True"/>\n                                        <field name="display_type" force_save="1" column_invisible="True"/>\n                                    </tree>\n                                    <kanban class="o_kanban_mobile">\n                                        <!-- Displayed fields -->\n                                        <field name="name"/>\n                                        <field name="product_id"/>\n                                        <field name="price_subtotal" string="Tax excl."/>\n                                        <field name="price_total" string="Tax incl." optional="hide"/>\n                                        <field name="quantity"/>\n                                        <field name="product_uom_category_id"/>\n                                        <field name="product_uom_id" groups="uom.group_uom"/>\n                                        <field name="price_unit"/>\n                                        <templates>\n                                            <t t-name="kanban-box">\n                                                <div t-attf-class="oe_kanban_card oe_kanban_global_click ps-0 pe-0 {{ record.display_type.raw_value ? 'o_is_' + record.display_type.raw_value : '' }}">\n                                                    <t t-if="!['line_note', 'line_section'].includes(record.display_type.raw_value)">\n                                                        <div class="row g-0">\n                                                            <div t-if="record.product_id.raw_value" class="col-2 pe-3">\n                                                                <img t-att-src="kanban_image('product.product', 'image_128', record.product_id.raw_value)" t-att-title="record.product_id.value" t-att-alt="record.product_id.value" style="max-width: 100%;"/>\n                                                            </div>\n                                                            <div t-att-class="{'col-10': record.product_id.raw_value}">\n                                                                <div class="row">\n                                                                    <div class="col">\n                                                                        <strong t-if="record.product_id.raw_value" t-out="record.product_id.value"/>\n                                                                        <strong t-else="" t-out="record.name.value"/>\n                                                                    </div>\n                                                                    <div class="col-auto">\n                                                                        <strong class="float-end text-end">\n                                                                            <t t-out="record.price_subtotal.value"/>\n                                                                            <t t-out="record.price_total.value" t-if="tax_calculation_rounding_method == 'round_per_line'"/>\n                                                                        </strong>\n                                                                    </div>\n                                                                </div>\n                                                                <div class="text-muted">\n                                                                    Quantity:\n                                                                    <t t-out="record.quantity.value"/>\n                                                                    <t t-out="record.product_uom_id.value" groups="uom.group_uom"/>\n                                                                </div>\n                                                                <div class="text-muted">\n                                                                    Unit Price:\n                                                                    <t t-out="record.price_unit.value"/>\n                                                                </div>\n                                                            </div>\n                                                        </div>\n                                                    </t>\n                                                    <t t-if="record.display_type.raw_value === 'line_section' || record.display_type.raw_value === 'line_note'">\n                                                        <div class="row">\n                                                            <div class="col-12">\n                                                                <t t-out="record.name.value"/>\n                                                            </div>\n                                                        </div>\n                                                    </t>\n                                                </div>\n                                            </t>\n                                        </templates>\n\n                                        <!-- Others fields -->\n                                        <field name="tax_calculation_rounding_method"/>\n                                        <field name="currency_id"/>\n                                        <field name="company_currency_id"/>\n                                        <field name="display_type" force_save="1"/>\n                                    </kanban>\n\n                                    <!-- Form view to cover mobile use -->\n                                    <form>\n                                        <sheet>\n                                            <field name="tax_calculation_rounding_method" invisible="1"/>\n                                            <field name="display_type" invisible="1"/>\n                                            <field name="company_id" invisible="1"/>\n                                            <field name="partner_id" invisible="1"/>\n                                            <group>\n                                                <field name="product_id" widget="many2one_barcode"/>\n                                                <field name="quantity"/>\n                                                <field name="product_uom_category_id" invisible="1"/>\n                                                <field name="product_uom_id" groups="uom.group_uom"/>\n                                                <field name="price_unit"/>\n                                                <field name="discount" string="Disc.%"/>\n                                            </group>\n                                            <group>\n                                                <field name="account_id" domain="[('company_id', 'parent_of', company_id), ('deprecated', '=', False)]" options="{'no_create': True}" context="{'partner_id': partner_id, 'move_type': parent.move_type}"/>\n                                                <field name="tax_ids" widget="many2many_tags"/>\n                                                <field name="analytic_distribution" widget="analytic_distribution" groups="analytic.group_analytic_accounting"/>\n                                            </group>\n                                            <label for="name" string="Description" invisible="display_type in ('line_note', 'line_section')"/>\n                                            <label for="name" string="Section" invisible="display_type != 'line_section'"/>\n                                            <label for="name" string="Note" invisible="display_type != 'line_note'"/>\n                                            <field name="name" widget="text"/>\n                                            <group>\n                                                <field name="price_subtotal" string="Tax excl."/>\n                                                <field name="price_total" string="Tax incl." invisible="tax_calculation_rounding_method == 'round_globally'" optional="hide"/>\n                                            </group>\n                                        </sheet>\n                                    </form>\n                                </field>\n                                <group col="12" class="oe_invoice_lines_tab">\n                                    <group colspan="8">\n                                        <field name="narration" placeholder="Terms and Conditions" colspan="2" nolabel="1"/>\n                                    </group>\n                                    <!-- Totals (only invoices / receipts) -->\n                                    <group colspan="4">\n                                        <group class="oe_subtotal_footer" invisible="move_type not in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') or payment_state == 'invoicing_legacy'">\n\n                                            <field name="tax_totals" widget="account-tax-totals-field" nolabel="1" colspan="2" readonly="state != 'draft' or (move_type not in ('in_invoice', 'in_refund', 'in_receipt') and not quick_edit_mode)"/>\n\n                                            <field name="invoice_payments_widget" colspan="2" nolabel="1" widget="payment"/>\n                                            <field name="amount_residual" class="oe_subtotal_footer_separator" invisible="state == 'draft'"/>\n                                        </group>\n                                        <field name="invoice_outstanding_credits_debits_widget" class="oe_invoice_outstanding_credits_debits" colspan="2" nolabel="1" widget="payment" invisible="state != 'posted'"/>\n                                    </group>\n                                </group>\n                            </page>\n                            <page id="aml_tab" string="Journal Items" groups="account.group_account_readonly" name="aml_tab">\n                                <field name="line_ids" mode="tree,kanban" context="{                                            'default_move_type': context.get('default_move_type'),                                            'line_ids': line_ids,                                            'journal_id': journal_id,                                            'default_partner_id': commercial_partner_id,                                            'default_currency_id': currency_id or company_currency_id,                                            'kanban_view_ref': 'account.account_move_line_view_kanban_mobile',                                        }" invisible="payment_state == 'invoicing_legacy' and move_type != 'entry'" readonly="state != 'draft'">\n                                    <tree editable="bottom" string="Journal Items" decoration-muted="display_type in ('line_section', 'line_note')" default_order="sequence, id">\n                                        <!-- Displayed fields -->\n                                        <field name="account_id" invisible="display_type in ('line_section', 'line_note')" required="display_type not in ('line_section', 'line_note')" domain="[('company_id', 'parent_of', parent.company_id), ('deprecated', '=', False)]"/>\n                                        <field name="partner_id" optional="show" domain="['|', ('parent_id', '=', False), ('is_company', '=', True)]" column_invisible="parent.move_type != 'entry'"/>\n                                        <field name="name" widget="section_and_note_text" optional="show"/>\n                                        <field name="analytic_distribution" widget="analytic_distribution" groups="analytic.group_analytic_accounting" optional="show" options="{'account_field': 'account_id'}" business_domain_compute="parent.move_type in ['out_invoice', 'out_refund', 'out_receipt'] and 'invoice' or parent.move_type in ['in_invoice', 'in_refund', 'in_receipt'] and 'bill' or 'general'"/>\n                                        <field name="date_maturity" optional="hide" invisible="display_type in ('line_section', 'line_note')" column_invisible="context.get('view_no_maturity')"/>\n                                        <field name="amount_currency" groups="base.group_multi_currency" optional="hide"/>\n                                        <field name="currency_id" options="{'no_create': True}" optional="hide" groups="base.group_multi_currency" column_invisible="parent.move_type != 'entry'"/>\n                                        <field name="tax_ids" widget="autosave_many2many_tags" optional="hide" domain="[('type_tax_use', '=?', parent.invoice_filter_type_domain)]" context="{'append_type_to_tax_name': not parent.invoice_filter_type_domain, 'active_test': True}" options="{'no_create': True}" force_save="1" readonly="display_type in ('line_section', 'line_note') or tax_line_id or (parent.move_type in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') and account_type in ('asset_receivable', 'liability_payable'))"/>\n                                        <field name="debit" sum="Total Debit" invisible="display_type in ('line_section', 'line_note')" readonly="parent.move_type in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') and display_type in ('line_section', 'line_note', 'product')"/>\n                                        <field name="credit" sum="Total Credit" invisible="display_type in ('line_section', 'line_note')" readonly="parent.move_type in ('out_invoice', 'out_refund', 'in_invoice', 'in_refund', 'out_receipt', 'in_receipt') and display_type in ('line_section', 'line_note', 'product')"/>\n                                        <field name="balance" column_invisible="True"/>\n                                        <field name="discount_date" string="Discount Date" optional="hide"/>\n                                        <field name="discount_amount_currency" string="Discount Amount" optional="hide"/>\n\n                                        <field name="tax_tag_ids" widget="many2many_tags" string="Tax Grids" optional="show" options="{'no_create': True}" domain="[                                                     ('applicability', '=', 'taxes'),                                                     '|', ('country_id', '=', parent.tax_country_id),                                                     ('country_id', '=', False),                                                 ]"/>\n\n                                        <field name="tax_tag_invert" readonly="1" optional="hide" groups="base.group_no_one"/>\n\n                                        <!-- Buttons -->\n                                        <button name="action_automatic_entry" type="object" icon="fa-calendar" string="Cut-Off" aria-label="Change Period" class="float-end" column_invisible="parent.move_type == 'entry' or parent.state != 'posted'" invisible="account_internal_group not in ('income', 'expense')" context="{'default_action': 'change_period'}"/>\n\n                