         <div t-attf-class=\\"#{'col-auto col-3 mw-100' if report_type != 'html' else 'col'} mb-2\\" t-if=\\"o.invoice_origin\\" name=\\"origin\\">\\n                                <strong>Source:</strong><br/>\\n                                <span t-field=\\"o.invoice_origin\\">SO123</span>\\n                            </div>\\n                            <div t-attf-class=\\"#{'col-auto col-3 mw-100' if report_type != 'html' else 'col'} mb-2\\" t-if=\\"o.partner_id.ref\\" name=\\"customer_code\\">\\n                                <strong>Customer Code:</strong><br/>\\n                                <span t-field=\\"o.partner_id.ref\\"/>\\n                            </div>\\n                            <div t-attf-class=\\"#{'col-auto col-3 mw-100' if report_type != 'html' else 'col'} mb-2\\" t-if=\\"o.ref\\" name=\\"reference\\">\\n                                <strong>Reference:</strong><br/>\\n                                <span t-field=\\"o.ref\\">INV/2023/00001</span>\\n                            </div>\\n                            <div t-attf-class=\\"#{'col-auto col-3 mw-100' if report_type != 'html' else 'col'} mb-2\\" t-if=\\"o.invoice_incoterm_id\\" name=\\"incoterm_id\\">\\n                                <strong>Incoterm:</strong><br/>\\n                                <p t-if=\\"o.incoterm_location\\">\\n                                    <span t-field=\\"o.invoice_incoterm_id.code\\"/> <br/>\\n                                    <span t-field=\\"o.incoterm_location\\"/>\\n                                </p>\\n                                <span t-else=\\"\\" t-field=\\"o.invoice_incoterm_id.code\\" class=\\"m-0\\"/>\\n                            </div>\\n                        </div>\\n\\n                        <t t-set=\\"display_discount\\" t-value=\\"any(l.discount for l in o.invoice_line_ids)\\"/>\\n                        <div class=\\"oe_structure\\"/>\\n                        <t t-set=\\"has_long_desc\\" t-value=\\"any(line.name and line.name.count('\\\\n') &gt; 30 for line in o.invoice_line_ids if line.name)\\"/>\\n                        <table class=\\"table table-sm o_main_table table-borderless\\" name=\\"invoice_line_table\\">\\n                            <thead t-attf-style=\\"#{has_long_desc and 'display: table-row-group;' or ''}\\">\\n                                <tr>\\n                                    <th name=\\"th_description\\" class=\\"text-start\\"><span>Description</span></th>\\n                                    <th name=\\"th_quantity\\" class=\\"text-end\\"><span>Quantity</span></th>\\n                                    <th name=\\"th_priceunit\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\"><span>Unit Price</span></th>\\n                                    <th name=\\"th_discount\\" t-if=\\"display_discount\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                        <span>Disc.%</span>\\n                                    </th>\\n                                    <th name=\\"th_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\"><span>Taxes</span></th>\\n                                    <th name=\\"th_subtotal\\" class=\\"text-end\\">\\n                                        <span>Amount</span>\\n                                    </th>\\n                                </tr>\\n                            </thead>\\n                            <tbody class=\\"invoice_tbody\\">\\n                                <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n                                <t t-set=\\"current_total\\" t-value=\\"0\\"/>\\n                                <t t-set=\\"lines\\" t-value=\\"o.invoice_line_ids.sorted(key=lambda l: (-l.sequence, l.date, l.move_name, -l.id), reverse=True)\\"/>\\n\\n                                <t t-foreach=\\"lines\\" t-as=\\"line\\">\\n                                    <t t-set=\\"current_subtotal\\" t-value=\\"current_subtotal + line.price_subtotal\\"/>\\n                                    <t t-set=\\"current_total\\" t-value=\\"current_total + line.price_total\\"/>\\n\\n                                    <tr t-att-class=\\"'bg-200 fw-bold o_line_section' if line.display_type == 'line_section' else 'fst-italic o_line_note' if line.display_type == 'line_note' else ''\\">\\n                                        <t t-if=\\"line.display_type == 'product'\\" name=\\"account_invoice_line_accountable\\">\\n                                            <td name=\\"account_invoice_line_name\\"><span t-if=\\"line.name\\" t-field=\\"line.name\\" t-options=\\"{'widget': 'text'}\\" dir=\\"auto\\">Bacon Burger</span></td>\\n                                            <td name=\\"td_quantity\\" class=\\"text-end\\">\\n                                                <span t-field=\\"line.quantity\\">3.00</span>\\n                                                <span t-field=\\"line.product_uom_id\\" groups=\\"uom.group_uom\\">units</span>\\n                                            </td>\\n                                            <td name=\\"td_price_unit\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                                <span class=\\"text-nowrap\\" t-field=\\"line.price_unit\\">9.00</span>\\n                                            </td>\\n                                            <td name=\\"td_discount\\" t-if=\\"display_discount\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}\\">\\n                                                <span class=\\"text-nowrap\\" t-field=\\"line.discount\\">0</span>\\n                                            </td>\\n                                            <t t-set=\\"taxes\\" t-value=\\"', '.join([(tax.invoice_label or tax.name) for tax in line.tax_ids])\\"/>\\n                                            <td name=\\"td_taxes\\" t-attf-class=\\"text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }} {{ 'text-nowrap' if len(taxes) &lt; 10 else '' }}\\">\\n                                                <span t-out=\\"taxes\\" id=\\"line_tax_ids\\">Tax 15%</span>\\n                                            </td>\\n                                            <td name=\\"td_subtotal\\" class=\\"text-end o_price_total\\">\\n                                                <span class=\\"text-nowrap\\" t-field=\\"line.price_subtotal\\">27.00</span>\\n                                            </td>\\n                                        </t>\\n                                        <t t-elif=\\"line.display_type == 'line_section'\\">\\n                                            <td colspan=\\"99\\">\\n                                                <span t-if=\\"line.name\\" t-field=\\"line.name\\" t-options=\\"{'widget': 'text'}\\" dir=\\"auto\\">A section title</span>\\n                                            </td>\\n                                            <t t-set=\\"current_section\\" t-value=\\"line\\"/>\\n                                            <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n                                        </t>\\n                                        <t t-elif=\\"line.display_type == 'line_note'\\">\\n                                            <td colspan=\\"99\\">\\n                                                <span t-if=\\"line.name\\" t-field=\\"line.name\\" t-options=\\"{'widget': 'text'}\\" dir=\\"auto\\">A note, whose content usually applies to the section or product above.</span>\\n                                            </td>\\n                                        </t>\\n                                    </tr>\\n\\n                                    <t t-if=\\"current_section and (line_last or lines[line_index+1].display_type == 'line_section')\\">\\n                                        <tr class=\\"is-subtotal text-end\\">\\n                                            <td colspan=\\"99\\">\\n                                                <strong class=\\"mr16\\">Subtotal</strong>\\n                                                <span t-out=\\"current_subtotal\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\">31.05</span>\\n                                            </td>\\n                                        </tr>\\n                                    </t>\\n                                </t>\\n                            </tbody>\\n                        </table>\\n                        <div>\\n                            <div id=\\"right-elements\\" t-attf-class=\\"#{'col-5' if report_type != 'html' else 'col-12 col-md-5'} ms-5 d-inline-block float-end\\">\\n                                <div id=\\"total\\" class=\\"clearfix row\\">\\n                                    <div class=\\"ms-auto\\">\\n                                        <table class=\\"table table-sm table-borderless avoid-page-break-inside\\">\\n\\n                                            <!--Tax totals-->\\n                                            <t t-set=\\"tax_totals\\" t-value=\\"o.tax_totals or {}\\"/>\\n                                            <t t-call=\\"account.document_tax_totals\\"/>\\n\\n                                            <!--Payments-->\\n                                            <t t-if=\\"print_with_payments\\">\\n                                                <t t-if=\\"o.payment_state != 'invoicing_legacy'\\">\\n                                                    <t t-set=\\"payments_vals\\" t-value=\\"o.sudo().invoice_payments_widget and o.sudo().invoice_payments_widget['content'] or []\\"/>\\n                                                    <t t-foreach=\\"payments_vals\\" t-as=\\"payment_vals\\">\\n                                                        <tr t-if=\\"payment_vals['is_exchange'] == 0\\">\\n                                                            <td>\\n                                                                <i class=\\"oe_form_field text-end oe_payment_label\\">Paid on <t t-out=\\"payment_vals['date']\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\">2021-09-19</t></i>\\n                                                            </td>\\n                                                            <td class=\\"text-end\\">\\n                                                                <span t-out=\\"payment_vals['amount']\\" t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\">20.00</span>\\n                                                            </td>\\n                                                        </tr>\\n                                                    </t>\\n                                                    <t t-if=\\"len(payments_vals) &gt; 0\\">\\n                                                        <tr class=\\"border-black fw-bold\\">\\n                                                            <td>Amount Due</td>\\n                                                            <td class=\\"text-end\\">\\n                                                                <span t-field=\\"o.amount_residual\\">11.05</span>\\n                                                            </td>\\n                                                        </tr>\\n                                                    </t>\\n                                                </t>\\n                                            </t>\\n                                        </table>\\n                                    </div>\\n                                </div>\\n                                <div class=\\"mb-2\\">\\n                                    <p class=\\"text-end lh-sm\\" t-if=\\"o.company_id.display_invoice_amount_total_words\\">\\n                                        Total amount in words: <br/>\\n                                        <small class=\\"text-muted lh-sm\\"><span t-field=\\"o.amount_total_words\\">Thirty one dollar and Five cents</span></small>\\n                                    </p>\\n                                </div>\\n                                <t t-call=\\"account.document_tax_totals_company_currency_template\\"/>\\n                            </div>\\n                            <div id=\\"payment_term\\" class=\\"clearfix\\">\\n                                <div class=\\"justify-text\\">\\n                                    <p t-if=\\"not is_html_empty(o.fiscal_position_id.note)\\" name=\\"note\\" class=\\"mb-2\\">\\n                                        <span t-field=\\"o.fiscal_position_id.note\\"/>\\n                                    </p>\\n                                </div>\\n                                <t t-set=\\"payment_term_details\\" t-value=\\"o.payment_term_details\\"/>\\n                                <div class=\\"mb-3\\">\\n                                    <span id=\\"payment_terms_note_id\\" t-if=\\"o.invoice_payment_term_id.note\\" t-field=\\"o.invoice_payment_term_id.note\\" name=\\"payment_term\\">Payment within 30 calendar day</span><br/>\\n                                    <t t-if=\\"o.invoice_payment_term_id.display_on_invoice and payment_term_details\\">\\n                                        <div t-if=\\"o.show_payment_term_details\\" id=\\"total_payment_term_details_table\\" class=\\"row\\">\\n                                            <div t-attf-class=\\"#{'col-10' if report_type != 'html' else 'col-sm-10 col-md-9'}\\">\\n                                                <t t-if=\\"o._is_eligible_for_early_payment_discount(o.currency_id,o.invoice_date)\\">\\n                                                    <td>\\n                                                        <span t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\" t-out=\\"o.invoice_payment_term_id._get_amount_due_after_discount(o.amount_total, o.amount_tax)\\">30.00</span> due if paid before\\n                                                        <span t-out=\\"o.invoice_payment_term_id._get_last_discount_date_formatted(o.invoice_date)\\">2024-01-01</span>\\n                                                    </td>\\n                                                </t>\\n                                                <t t-if=\\"len(payment_term_details) &gt; 1\\" t-foreach=\\"payment_term_details\\" t-as=\\"term\\">\\n                                                    <div>\\n                                                        <span t-out=\\"term_index + 1\\">1</span> - Installment of\\n                                                        <t t-options=\\"{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}\\" t-out=\\"term.get('amount')\\" class=\\"text-end\\">31.05</t>\\n                                                        <span> due on </span>\\n                                                        <t t-out=\\"term.get('date')\\" class=\\"text-start\\">2024-01-01</t>\\n                                                    </div>\\n                                                </t>\\n                                            </div>\\n                                        </div>\\n                                    </t>\\n                                </div>\\n                                <div class=\\"mb-3\\" t-if=\\"o.move_type in ('out_invoice', 'in_refund') and o.payment_reference\\">\\n                                    <p name=\\"payment_communication\\">\\n                                        Payment Communication: <span class=\\"fw-bold\\" t-field=\\"o.payment_reference\\">INV/2023/00001</span>\\n                                        <t t-if=\\"o.partner_bank_id\\">\\n                                            <br/> on this account: <span t-field=\\"o.partner_bank_id\\" class=\\"fw-bold\\"/>\\n                                        </t>\\n                                    </p>\\n                                </div>\\n                                <t t-set=\\"show_qr\\" t-value=\\"o.display_qr_code and o.amount_residual &gt; 0\\"/>\\n                                <div t-if=\\"not show_qr\\" name=\\"qr_code_placeholder\\" class=\\"oe_structure\\"/>\\n                                <div id=\\"qrcode\\" class=\\"d-flex mb-3 avoid-page-break-inside\\" t-else=\\"\\">\\n                                    <div class=\\"qrcode me-3\\" id=\\"qrcode_image\\">\\n                                        <t t-set=\\"qr_code_url\\" t-value=\\"o._generate_qr_code(silent_errors=True)\\"/>\\n                                        <p t-if=\\"qr_code_url\\" class=\\"position-relative mb-0\\">\\n                                            <img t-att-src=\\"qr_code_url\\"/>\\n                                            <img src=\\"/account/static/src/img/Odoo_logo_O.svg\\" id=\\"qrcode_odoo_logo\\" class=\\"top-50 start-50 position-absolute bg-white border border-white border-3 rounded-circle\\"/>\\n                                        </p>\\n                                    </div>\\n                                    <div class=\\"d-inline text-muted lh-sm fst-italic\\" id=\\"qrcode_info\\" t-if=\\"qr_code_url\\">\\n                                        <p>Scan this QR Code to<br/>pay with your mobile</p>\\n                                    </div>\\n                                </div>\\n                                <!--terms and conditions-->\\n                                <div class=\\"text-muted mb-3\\" t-attf-style=\\"#{'text-align:justify;text-justify:inter-word;' if o.company_id.terms_type != 'html' else ''}\\" t-if=\\"not is_html_empty(o.narration)\\" name=\\"comment\\">\\n                                    <span t-field=\\"o.narration\\"/>\\n                                </div>\\n                            </div>\\n                        </div>\\n                    </div>\\n                </div>\\n            </t>\\n        </t>"}	<?xml version="1.0"?>\n<t t-name="account.report_invoice_document">\n            <t t-call="web.external_layout">\n                <t t-set="o" t-value="o.with_context(lang=lang)"/>\n                <t t-set="forced_vat" t-value="o.fiscal_position_id.foreign_vat"/> <!-- So that it appears in the footer of the report instead of the company VAT if it's set -->\n                <div class="row">\n                    <t t-if="o.partner_shipping_id and (o.partner_shipping_id != o.partner_id)">\n                        <div class="col-6">\n                            <t t-set="information_block">\n                                <div groups="account.group_delivery_invoice_address" name="shipping_address_block">\n                                    <strong>Shipping Address:</strong>\n                                    <div t-field="o.partner_shipping_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>\n                                </div>\n                            </t>\n                        </div>\n                        <div class="col-6" name="address_not_same_as_shipping">\n                            <t t-set="address">\n                                <address class="mb-0" t-field="o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>\n                                <div t-if="o.partner_id.vat" id="partner_vat_address_not_same_as_shipping">\n                                    <t t-if="o.company_id.account_fiscal_country_id.vat_label" t-out="o.company_id.account_fiscal_country_id.vat_label" id="inv_tax_id_label"/>\n                                    <t t-else="">Tax ID</t>: <span t-field="o.partner_id.vat"/>\n                                </div>\n                                <div t-if="o.partner_id.country_code == 'MA' and o.partner_id.company_registry">\n                                    ICE: <a t-field="o.partner_id.company_registry"/>\n                                </div>\n                            </t>\n                        </div>\n                    </t>\n                    <t t-elif="o.partner_shipping_id and (o.partner_shipping_id == o.partner_id)">\n                        <div class="offset-col-6 col-6" name="address_same_as_shipping">\n                            <t t-set="address">\n                                <address class="mb-0" t-field="o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>\n                                <div t-if="o.partner_id.vat" id="partner_vat_address_same_as_shipping">\n                                    <t t-if="o.company_id.account_fiscal_country_id.vat_label" t-out="o.company_id.account_fiscal_country_id.vat_label" id="inv_tax_id_label"/>\n                                    <t t-else="">Tax ID</t>: <span t-field="o.partner_id.vat"/>\n                                </div>\n                                <div t-if="o.partner_id.country_code == 'MA' and o.partner_id.company_registry">\n                                    ICE: <a t-field="o.partner_id.company_registry"/>\n                                </div>\n                            </t>\n                        </div>\n                    </t>\n                    <t t-else="">\n                        <div class="offset-col-6 col-6" name="no_shipping">\n                            <t t-set="address">\n                                <address class="mb-0" t-field="o.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>\n                                <div t-if="o.partner_id.vat" id="partner_vat_no_shipping">\n                                    <t t-if="o.company_id.account_fiscal_country_id.vat_label" t-out="o.company_id.account_fiscal_country_id.vat_label" id="inv_tax_id_label"/>\n                                    <t t-else="">Tax ID</t>: <span t-field="o.partner_id.vat"/>\n                                </div>\n                                <div t-if="o.partner_id.country_code == 'MA' and o.partner_id.company_registry">\n                                    ICE: <a t-field="o.partner_id.company_registry"/>\n                                </div>\n                            </t>\n                        </div>\n                    </t>\n                </div>\n                <div class="mt-5 clearfix">\n                    <div class="page mb-4">\n                        <h2>\n                            <span t-if="not proforma"/>\n                            <span t-else="">PROFORMA</span>\n                            <span t-if="o.move_type == 'out_invoice' and o.state == 'posted'">Invoice</span>\n                            <span t-elif="o.move_type == 'out_invoice' and o.state == 'draft'">Draft Invoice</span>\n                            <span t-elif="o.move_type == 'out_invoice' and o.state == 'cancel'">Cancelled Invoice</span>\n                            <span t-elif="o.move_type == 'out_refund' and o.state == 'posted'">Credit Note</span>\n                            <span t-elif="o.move_type == 'out_refund' and o.state == 'draft'">Draft Credit Note</span>\n                            <span t-elif="o.move_type == 'out_refund' and o.state == 'cancel'">Cancelled Credit Note</span>\n                            <span t-elif="o.move_type == 'in_refund'">Vendor Credit Note</span>\n                            <span t-elif="o.move_type == 'in_invoice'">Vendor Bill</span>\n                            <span t-if="o.name != '/'" t-field="o.name">INV/2023/0001</span>\n                        </h2>\n                        <div class="oe_structure"/>\n                        <div id="informations" class="row mt-3 mb-1">\n                            <div t-attf-class="#{'col-auto col-3 mw-100' if report_type != 'html' else 'col'} mb-2" t-if="o.invoice_date" name="invoice_date">\n                                <t t-if="o.move_type == 'out_invoice'"><strong>Invoice Date:</strong></t>\n                                <t t-elif="o.move_type == 'out_refund'"><strong>Credit Note Date:</strong></t>\n                                <t t-elif="o.move_type == 'out_receipt'"><strong>Receipt Date:</strong></t>\n                                <t t-else=""><strong>Date:</strong></t><br/>\n                                <span t-field="o.invoice_date">2023-09-12</span>\n                            </div>\n                            <div t-attf-class="#{'col-auto col-3 mw-100' if report_type != 'html' else 'col'} mb-2" t-if="o.invoice_date_due and o.move_type == 'out_invoice' and o.state == 'posted'" name="due_date">\n                                <strong>Due Date:</strong><br/>\n                                <span t-field="o.invoice_date_due">2023-10-31</span>\n                            </div>\n                            <div t-attf-class="#{'col-auto col-3 mw-100' if report_type != 'html' else 'col'} mb-2" t-if="o.delivery_date" name="delivery_date">\n                                <strong>Delivery Date:</strong><br/>\n                                <span t-field="o.delivery_date">2023-09-25</span>\n                            </div>\n                            <div t-attf-class="#{'col-auto col-3 mw-100' if report_type != 'html' else 'col'} mb-2" t-if="o.invoice_origin" name="origin">\n                                <strong>Source:</strong><br/>\n                                <span t-field="o.invoice_origin">SO123</span>\n                            </div>\n                            <div t-attf-class="#{'col-auto col-3 mw-100' if report_type != 'html' else 'col'} mb-2" t-if="o.partner_id.ref" name="customer_code">\n                                <strong>Customer Code:</strong><br/>\n                                <span t-field="o.partner_id.ref"/>\n                            </div>\n                            <div t-attf-class="#{'col-auto col-3 mw-100' if report_type != 'html' else 'col'} mb-2" t-if="o.ref" name="reference">\n                                <strong>Reference:</strong><br/>\n                                <span t-field="o.ref">INV/2023/00001</span>\n                            </div>\n                            <div t-attf-class="#{'col-auto col-3 mw-100' if report_type != 'html' else 'col'} mb-2" t-if="o.invoice_incoterm_id" name="incoterm_id">\n                                <strong>Incoterm:</strong><br/>\n                                <p t-if="o.incoterm_location">\n                                    <span t-field="o.invoice_incoterm_id.code"/> <br/>\n                                    <span t-field="o.incoterm_location"/>\n                                </p>\n                                <span t-else="" t-field="o.invoice_incoterm_id.code" class="m-0"/>\n                            </div>\n                        </div>\n\n                        <t t-set="display_discount" t-value="any(l.discount for l in o.invoice_line_ids)"/>\n                        <div class="oe_structure"/>\n                        <t t-set="has_long_desc" t-value="any(line.name and line.name.count('\\n') &gt; 30 for line in o.invoice_line_ids if line.name)"/>\n                        <table class="table table-sm o_main_table table-borderless" name="invoice_line_table">\n                            <thead t-attf-style="#{has_long_desc and 'display: table-row-group;' or ''}">\n                                <tr>\n                                    <th name="th_description" class="text-start"><span>Description</span></th>\n                                    <th name="th_quantity" class="text-end"><span>Quantity</span></th>\n                                    <th name="th_priceunit" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}"><span>Unit Price</span></th>\n                                    <th name="th_discount" t-if="display_discount" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}">\n                                        <span>Disc.%</span>\n                                    </th>\n                                    <th name="th_taxes" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}"><span>Taxes</span></th>\n                                    <th name="th_subtotal" class="text-end">\n                                        <span>Amount</span>\n                                    </th>\n                                </tr>\n                            </thead>\n                            <tbody class="invoice_tbody">\n                                <t t-set="current_subtotal" t-value="0"/>\n                                <t t-set="current_total" t-value="0"/>\n                                <t t-set="lines" t-value="o.invoice_line_ids.sorted(key=lambda l: (-l.sequence, l.date, l.move_name, -l.id), reverse=True)"/>\n\n                                <t t-foreach="lines" t-as="line">\n                                    <t t-set="current_subtotal" t-value="current_subtotal + line.price_subtotal"/>\n                                    <t t-set="current_total" t-value="current_total + line.price_total"/>\n\n                                    <tr t-att-class="'bg-200 fw-bold o_line_section' if line.display_type == 'line_section' else 'fst-italic o_line_note' if line.display_type == 'line_note' else ''">\n                                        <t t-if="line.display_type == 'product'" name="account_invoice_line_accountable">\n                                            <td name="account_invoice_line_name"><span t-if="line.name" t-field="line.name" t-options="{'widget': 'text'}" dir="auto">Bacon Burger</span></td>\n                                            <td name="td_quantity" class="text-end">\n                                                <span t-field="line.quantity">3.00</span>\n                                                <span t-field="line.product_uom_id" groups="uom.group_uom">units</span>\n                                            </td>\n                                            <td name="td_price_unit" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}">\n                                                <span class="text-nowrap" t-field="line.price_unit">9.00</span>\n                                            </td>\n                                            <td name="td_discount" t-if="display_discount" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }}">\n                                                <span class="text-nowrap" t-field="line.discount">0</span>\n                                            </td>\n                                            <t t-set="taxes" t-value="', '.join([(tax.invoice_label or tax.name) for tax in line.tax_ids])"/>\n                                            <td name="td_taxes" t-attf-class="text-end {{ 'd-none d-md-table-cell' if report_type == 'html' else '' }} {{ 'text-nowrap' if len(taxes) &lt; 10 else '' }}">\n                                                <span t-out="taxes" id="line_tax_ids">Tax 15%</span>\n                                            </td>\n                                            <td name="td_subtotal" class="text-end o_price_total">\n                                                <span class="text-nowrap" t-field="line.price_subtotal">27.00</span>\n                                            </td>\n                                        </t>\n                                        <t t-elif="line.display_type == 'line_section'">\n                                            <td colspan="99">\n                                                <span t-if="line.name" t-field="line.name" t-options="{'widget': 'text'}" dir="auto">A section title</span>\n                                            </td>\n                                            <t t-set="current_section" t-value="line"/>\n                                            <t t-set="current_subtotal" t-value="0"/>\n                                        </t>\n                                        <t t-elif="line.display_type == 'line_note'">\n                                            <td colspan="99">\n                                                <span t-if="line.name" t-field="line.name" t-options="{'widget': 'text'}" dir="auto">A note, whose content usually applies to the section or product above.</span>\n                                            </td>\n                                        </t>\n                                    </tr>\n\n                                    <t t-if="current_section and (line_last or lines[line_index+1].display_type == 'line_section')">\n                                        <tr class="is-subtotal text-end">\n                                            <td colspan="99">\n                                                <strong class="mr16">Subtotal</strong>\n                                                <span t-out="current_subtotal" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}">31.05</span>\n                                            </td>\n                                        </tr>\n                                    </t>\n                                </t>\n                            </tbody>\n                        </table>\n                        <div>\n                            <div id="right-elements" t-attf-class="#{'col-5' if report_type != 'html' else 'col-12 col-md-5'} ms-5 d-inline-block float-end">\n                                <div id="total" class="clearfix row">\n                                    <div class="ms-auto">\n                                        <table class="table table-sm table-borderless avoid-page-break-inside">\n\n                                            <!--Tax totals-->\n                                            <t t-set="tax_totals" t-value="o.tax_totals or {}"/>\n                                            <t t-call="account.document_tax_totals"/>\n\n                                            <!--Payments-->\n                                            <t t-if="print_with_payments">\n                                                <t t-if="o.payment_state != 'invoicing_legacy'">\n                                                    <t t-set="payments_vals" t-value="o.sudo().invoice_payments_widget and o.sudo().invoice_payments_widget['content'] or []"/>\n                                                    <t t-foreach="payments_vals" t-as="payment_vals">\n                                                        <tr t-if="payment_vals['is_exchange'] == 0">\n                                                            <td>\n                                                                <i class="oe_form_field text-end oe_payment_label">Paid on <t t-out="payment_vals['date']" t-options="{&quot;widget&quot;: &quot;date&quot;}">2021-09-19</t></i>\n                                                            </td>\n                                                            <td class="text-end">\n                                                                <span t-out="payment_vals['amount']" t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}">20.00</span>\n                                                            </td>\n                                                        </tr>\n                                                    </t>\n                                                    <t t-if="len(payments_vals) &gt; 0">\n                                                        <tr class="border-black fw-bold">\n                                                            <td>Amount Due</td>\n                                                            <td class="text-end">\n                                                                <span t-field="o.amount_residual">11.05</span>\n                                                            </td>\n                                                        </tr>\n                                                    </t>\n                                                </t>\n                                            </t>\n                                        </table>\n                                    </div>\n                                </div>\n                                <div class="mb-2">\n                                    <p class="text-end lh-sm" t-if="o.company_id.display_invoice_amount_total_words">\n                                        Total amount in words: <br/>\n                                        <small class="text-muted lh-sm"><span t-field="o.amount_total_words">Thirty one dollar and Five cents</span></small>\n                                    </p>\n                                </div>\n                                <t t-call="account.document_tax_totals_company_currency_template"/>\n                            </div>\n                            <div id="payment_term" class="clearfix">\n                                <div class="justify-text">\n                                    <p t-if="not is_html_empty(o.fiscal_position_id.note)" name="note" class="mb-2">\n                                        <span t-field="o.fiscal_position_id.note"/>\n                                    </p>\n                                </div>\n                                <t t-set="payment_term_details" t-value="o.payment_term_details"/>\n                                <div class="mb-3">\n                                    <span id="payment_terms_note_id" t-if="o.invoice_payment_term_id.note" t-field="o.invoice_payment_term_id.note" name="payment_term">Payment within 30 calendar day</span><br/>\n                                    <t t-if="o.invoice_payment_term_id.display_on_invoice and payment_term_details">\n                                        <div t-if="o.show_payment_term_details" id="total_payment_term_details_table" class="row">\n                                            <div t-attf-class="#{'col-10' if report_type != 'html' else 'col-sm-10 col-md-9'}">\n                                                <t t-if="o._is_eligible_for_early_payment_discount(o.currency_id,o.invoice_date)">\n                                                    <td>\n                                                        <span t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}" t-out="o.invoice_payment_term_id._get_amount_due_after_discount(o.amount_total, o.amount_tax)">30.00</span> due if paid before\n                                                        <span t-out="o.invoice_payment_term_id._get_last_discount_date_formatted(o.invoice_date)">2024-01-01</span>\n                                                    </td>\n                                                </t>\n                                                <t t-if="len(payment_term_details) &gt; 1" t-foreach="payment_term_details" t-as="term">\n                                                    <div>\n                                                        <span t-out="term_index + 1">1</span> - Installment of\n                                                        <t t-options="{&quot;widget&quot;: &quot;monetary&quot;, &quot;display_currency&quot;: o.currency_id}" t-out="term.get('amount')" class="text-end">31.05</t>\n                                                        <span> due on </span>\n                                                        <t t-out="term.get('date')" class="text-start">2024-01-01</t>\n                                                    </div>\n                                                </t>\n                                            </div>\n                                        </div>\n                                    </t>\n                                </div>\n                                <div class="mb-3" t-if="o.move_type in ('out_invoice', 'in_refund') and o.payment_reference">\n                                    <p name="payment_communication">\n                                        Payment Communication: <span class="fw-bold" t-field="o.payment_reference">INV/2023/00001</span>\n                                        <t t-if="o.partner_bank_id">\n                                            <br/> on this account: <span t-field="o.partner_bank_id" class="fw-bold"/>\n                                        </t>\n                                    </p>\n                                </div>\n                                <t t-set="show_qr" t-value="o.display_qr_code and o.amount_residual &gt; 0"/>\n                                <div t-if="not show_qr" name="qr_code_placeholder" class="oe_structure"/>\n                                <div id="qrcode" class="d-flex mb-3 avoid-page-break-inside" t-else="">\n                                    <div class="qrcode me-3" id="qrcode_image">\n                                        <t t-set="qr_code_url" t-value="o._generate_qr_code(silent_errors=True)"/>\n                                        <p t-if="qr_code_url" class="position-relative mb-0">\n                                            <img t-att-src="qr_code_url"/>\n                                            <img src="/account/static/src/img/Odoo_logo_O.svg" id="qrcode_odoo_logo" class="top-50 start-50 position-absolute bg-white border border-white border-3 rounded-circle"/>\n                                        </p>\n                                    </div>\n                                    <div class="d-inline text-muted lh-sm fst-italic" id="qrcode_info" t-if="qr_code_url">\n                                        <p>Scan this QR Code to<br/>pay with your mobile</p>\n                                    </div>\n                                </div>\n                                <!--terms and conditions-->\n                                <div class="text-muted mb-3" t-attf-style="#{'text-align:justify;text-justify:inter-word;' if o.company_id.terms_type != 'html' else ''}" t-if="not is_html_empty(o.narration)" name="comment">\n                                    <span t-field="o.narration"/>\n                                </div>\n                            </div>\n                        </div>\n                    </div>\n                </div>\n            </t>\n        </t>\n\n        	f	t	2026-09-17 06:40:24.625829	2026-09-17 06:40:24.625829	f
