le=\\"separator\\">New</span>\\n                                    </h5>\\n                                    <div t-if=\\"journal_type == 'bank'\\" name=\\"bank_new_actions\\">\\n                                        <a role=\\"menuitem\\" type=\\"object\\" name=\\"action_new_transaction\\" groups=\\"account.group_account_invoice\\">New Transaction</a>\\n                                    </div>\\n                                    <div name=\\"bank_customer_payment\\">\\n                                        <a role=\\"menuitem\\" type=\\"object\\" name=\\"create_customer_payment\\">Customer Payment</a>\\n                                    </div>\\n                                    <div>\\n                                        <a role=\\"menuitem\\" type=\\"object\\" name=\\"create_supplier_payment\\">Vendor Payment</a>\\n                                    </div>\\n                                </div>\\n\\n                            </div>\\n\\n                            <!-- For purchase and sale -->\\n                            <div t-if=\\"journal_type == 'purchase' || journal_type == 'sale'\\" class=\\"row\\">\\n                                <div class=\\"col-4 o_kanban_card_manage_section o_kanban_manage_view\\">\\n                                    <h5 class=\\"o_kanban_card_manage_title\\">\\n                                        <span>View</span>\\n                                    </h5>\\n                                    <div>\\n                                        <a t-if=\\"journal_type == 'sale'\\" type=\\"object\\" name=\\"open_action\\" context=\\"{'action_name': 'action_move_out_invoice_type'}\\">Invoices</a>\\n                                        <a t-if=\\"journal_type == 'purchase'\\" type=\\"object\\" name=\\"open_action\\" context=\\"{'action_name': 'action_move_in_invoice_type'}\\">Bills</a>\\n                                    </div>\\n                                    <div id=\\"sale_purchase_refund\\">\\n                                        <a t-if=\\"journal_type == 'sale'\\" type=\\"object\\" name=\\"open_action\\" context=\\"{'action_name': 'action_move_out_refund_type'}\\">Credit Notes</a>\\n                                        <a t-if=\\"journal_type == 'purchase'\\" type=\\"object\\" name=\\"open_action\\" context=\\"{'action_name': 'action_move_in_refund_type'}\\">Refund</a>\\n                                    </div>\\n                                    <div>\\n                                        <a type=\\"object\\" name=\\"open_action\\" context=\\"{'action_name': 'action_account_moves_all_a'}\\" groups=\\"base.group_no_one\\">Journal Items</a>\\n                                    </div>\\n                                </div>\\n\\n                                <div class=\\"col-4 o_kanban_card_manage_section o_kanban_manage_new\\" groups=\\"account.group_account_invoice\\">\\n                                    <h5 class=\\"o_kanban_card_manage_title\\">\\n                                        <span>New</span>\\n                                    </h5>\\n                                    <div>\\n                                        <a type=\\"object\\" name=\\"action_create_new\\">\\n                                            <span t-if=\\"journal_type == 'sale'\\">Invoice</span>\\n                                            <span t-if=\\"journal_type == 'purchase'\\">Bill</span>\\n                                        </a>\\n                                    </div>\\n                                    <div>\\n                                        <a type=\\"object\\" name=\\"action_create_new\\" context=\\"{'refund':True}\\">\\n                                            <span t-if=\\"journal_type == 'sale'\\">Credit Note</span>\\n                                            <span t-if=\\"journal_type == 'purchase'\\">Refund</span>\\n                                        </a>\\n                                    </div>\\n                                    <div t-if=\\"journal_type == 'sale'\\">\\n                                        <widget name=\\"account_file_uploader\\" title=\\"Upload Invoices\\" btnClass=\\"file_upload_kanban_action_a\\"/>\\n                                    </div>\\n                                </div>\\n\\n                                <div class=\\"col-4 o_kanban_card_manage_section o_kanban_manage_reports\\">\\n                                    <h5 class=\\"o_kanban_card_manage_title\\">\\n                                        <span>Reporting</span>\\n                                    </h5>\\n                                    <div>\\n                                        <a t-if=\\"journal_type == 'sale'\\" type=\\"action\\" name=\\"287\\" groups=\\"account.group_account_readonly\\">Invoices Analysis</a>\\n                                        <a t-if=\\"journal_type == 'purchase'\\" type=\\"action\\" name=\\"286\\" groups=\\"account.group_account_readonly\\">Bills Analysis</a>\\n                                    </div>\\n                                </div>\\n                            </div>\\n\\n                            <!-- For general and situation -->\\n                            <div t-if=\\"journal_type == 'general' || journal_type == 'situation'\\" class=\\"row\\">\\n                                <div class=\\"col-4 o_kanban_card_manage_section o_kanban_manage_view\\">\\n                                    <h5 class=\\"o_kanban_card_manage_title\\">\\n                                        <span>View</span>\\n                                    </h5>\\n                                    <div>\\n                                        <a type=\\"object\\" name=\\"open_action\\" context=\\"{'action_name': 'action_move_journal_line'}\\">Journal Entries</a>\\n                                    </div>\\n                                    <div>\\n                                        <a type=\\"object\\" name=\\"open_action\\" context=\\"{'action_name': 'action_move_journal_line', 'search_default_unposted': 1}\\">Entries to Review</a>\\n                                    </div>\\n                                    <div>\\n                                        <a type=\\"object\\" name=\\"open_action\\" context=\\"{'action_name': 'action_account_moves_all_a'}\\" groups=\\"base.group_no_one\\">Journal Items</a>\\n                                    </div>\\n                                </div>\\n\\n                                <div class=\\"col-4 o_kanban_card_manage_section o_kanban_manage_new\\" groups=\\"account.group_account_user\\">\\n                                    <h5 class=\\"o_kanban_card_manage_title\\">\\n                                        <span>New</span>\\n                                    </h5>\\n                                    <div>\\n                                        <a type=\\"object\\" name=\\"action_create_new\\">Journal Entry</a>\\n                                    </div>\\n                                </div>\\n\\n                                <div class=\\"col-4 o_kanban_card_manage_section o_kanban_manage_operations\\">\\n                                    <h5 class=\\"o_kanban_card_manage_title\\">\\n                                        <span>Operations</span>\\n                                    </h5>\\n                                    <div>\\n                                        <a type=\\"object\\" name=\\"open_action_with_context\\" context=\\"{'action_name': 'action_validate_account_move', 'search_default_journal': True}\\" groups=\\"account.group_account_user\\">Post All Entries</a>\\n                                    </div>\\n                                </div>\\n                            </div>\\n\\n                            <div t-if=\\"widget.editable\\" class=\\"o_kanban_card_manage_settings row\\">\\n                                <div class=\\"col-8\\">\\n                                    <ul class=\\"oe_kanban_colorpicker\\" data-field=\\"color\\"/>\\n                                </div>\\n                            </div>\\n\\n                            <div groups=\\"account.group_account_manager\\" class=\\"row o_kanban_card_manage_settings\\">\\n                                <field name=\\"show_on_dashboard\\" widget=\\"boolean_favorite\\" class=\\"col-6\\"/>\\n                                <div class=\\"col-6 text-end\\">\\n                                    <a class=\\"dropdown-item\\" t-if=\\"widget.editable\\" type=\\"edit\\">Configuration</a>\\n                                </div>\\n                            </div>\\n                        </div>\\n                    </t>\\n\\n                    <t t-name=\\"JournalMiscelaneous\\">\\n                        <div class=\\"col-12 col-sm-4 mb-3 mb-sm-0 o_kanban_primary_left\\">\\n                            <button id=\\"new_misc_entry_button\\" type=\\"object\\" name=\\"action_create_new\\" class=\\"btn btn-primary\\" groups=\\"account.group_account_invoice\\">\\n                                <span>New Entry</span>\\n                            </button>\\n                        </div>\\n                        <div class=\\"col-12 col-sm-8 o_kanban_primary_right\\">\\n                            <field name=\\"json_activity_data\\" widget=\\"kanban_vat_activity\\"/>\\n                            <t t-if=\\"dashboard.number_to_check &gt; 0\\">\\n                                <div class=\\"row\\">\\n                                    <div class=\\"col overflow-hidden text-start\\">\\n                                        <a type=\\"object\\" name=\\"open_action\\" context=\\"{'action_name': 'action_move_journal_line', 'search_default_to_check': True}\\"><t t-out=\\"dashboard.number_to_check\\"/> to check</a>\\n                                    </div>\\n                                    <div class=\\"col-auto text-end\\">\\n                                        <span class=\\"o_kanban_monetary\\"><t t-out=\\"dashboard.to_check_balance\\"/></span>\\n                                    </div>\\n                                </div>\\n                            </t>\\n                        </div>\\n                    </t>\\n\\n                    <t t-name=\\"JournalBodyBankCash\\">\\n                        <!-- On the left, display :\\n                            - A button corresponding to the bank_statements_source, if it wasn't configured, a button for each of them\\n                            - If there are statements to reconcile, a link to reconcile them -->\\n                        <div id=\\"dashboard_bank_cash_left\\" class=\\"col-12 col-sm-5 mb-3 mb-sm-0 o_kanban_primary_left\\">\\n                            <t t-if=\\"journal_type == 'bank'\\">\\n                                <t t-if=\\"['undefined', 'online_sync'].includes(dashboard.bank_statements_source)\\">\\n                                    <button name=\\"action_configure_bank_journal\\" type=\\"object\\" class=\\"btn btn-primary\\" groups=\\"account.group_account_invoice\\">Connect</button>\\n                                </t>\\n                                <div id=\\"transactions\\" class=\\"d-flex mt-3 mt-sm-0\\" style=\\"gap: 5px;\\">\\n                                    <div name=\\"bank_journal_cta\\" class=\\"w-100\\">\\n                                        <div t-if=\\"['undefined', 'file_import'].includes(dashboard.bank_statements_source)\\" name=\\"bank_journal_transactions\\" class=\\"w-100 d-flex\\" style=\\"gap: 5px;\\">\\n                                            <a id=\\"create_transaction\\" name=\\"action_new_transaction\\" type=\\"object\\" groups=\\"account.group_account_invoice\\">New Transaction</a>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </t>\\n                            <t t-if=\\"journal_type == 'cash'\\">\\n                                <button t-if=\\"dashboard.number_to_reconcile == 0\\" type=\\"object\\" name=\\"action_new_transaction\\" class=\\"btn btn-primary\\" groups=\\"account.group_account_invoice\\">New Transaction</button>\\n                                <a t-if=\\"dashboard.number_to_reconcile &gt; 0\\" type=\\"object\\" name=\\"action_new_transaction\\" class=\\"oe_inline\\" groups=\\"account.group_account_invoice\\">New Transaction</a>\\n                            </t>\\n                        </div>\\n                        <!-- On the right, show other common informations/actions -->\\n                        <div id=\\"dashboard_bank_cash_right\\" class=\\"col-12 col-sm-7 o_kanban_primary_right\\">\\n                            <div class=\\"row\\" t-if=\\"dashboard.nb_lines_bank_account_balance &gt; 0\\">\\n                                <div id=\\"dashboard_bank_cash_balance\\" class=\\"col overflow-hidden text-start\\">\\n                                    <span>Balance</span>\\n                                </div>\\n                                <div class=\\"col-auto text-end\\">\\n                                    <span class=\\"o_kanban_monetary\\"><t t-out=\\"dashboard.account_balance\\"/></span>\\n                                </div>\\n                            </div>\\n                            <t t-if=\\"dashboard.has_at_least_one_statement and dashboard.account_balance != dashboard.last_balance\\">\\n                                <div class=\\"row\\" name=\\"latest_statement\\">\\n                                    <div class=\\"col overflow-hidden text-start\\">\\n                                        <span title=\\"Latest Statement\\">Last Statement</span>\\n                                    </div>\\n                                    <div class=\\"col-auto text-end\\">\\n                                        <span class=\\"o_kanban_monetary\\"><t t-out=\\"dashboard.last_balance\\"/></span>\\n                                    </div>\\n                                </div>\\n                            </t>\\n                            <div class=\\"row\\" t-if=\\"dashboard.nb_lines_outstanding_pay_account_balance &gt; 0\\">\\n                                <div id=\\"dashboard_bank_cash_outstanding_balance\\" class=\\"col overflow-hidden text-start\\">\\n                                    <span title=\\"Outstanding Payments/Receipts\\">Payments</span>\\n                                </div>\\n                                <div class=\\"col-auto text-end\\">\\n                                    <span><t t-out=\\"dashboard.outstanding_pay_account_balance\\"/></span>\\n                                </div>\\n                            </div>\\n                            <div class=\\"row\\" t-if=\\"dashboard.nb_misc_operations &gt; 0\\">\\n                                <div id=\\"dashboard_bank_cash_misc_total\\" class=\\"col text-start\\">\\n                                    <a type=\\"object\\" name=\\"open_bank_difference_action\\" t-att-class=\\"dashboard.misc_class\\">Misc. Operations</a>\\n                                </div>\\n                                <div class=\\"col-auto text-end\\">\\n                                    <span><t t-out=\\"dashboard.misc_operations_balance\\"/></span>\\n                                </div>\\n                            </div>\\n                        </div>\\n                    </t>\\n                    <t t-name=\\"JournalBodySalePurchase\\" id=\\"account.JournalBodySalePurchase\\">\\n                        <div class=\\"col-12 col-sm-5 mb-3 mb-sm-0 o_kanban_primary_left\\">\\n                            <t t-if=\\"journal_type == 'sale'\\">\\n                                <button type=\\"object\\" name=\\"action_create_new\\" class=\\"btn btn-primary o_invoice_new\\" groups=\\"account.group_account_invoice\\">\\n                                    <span>New Invoice</span>\\n                                </button>\\n                            </t>\\n                            <t t-if=\\"journal_type == 'purchase'\\">\\n                                <t t-if=\\"dashboard.entries_count &gt; 0\\">\\n                                    <widget name=\\"account_file_uploader\\" btnClass=\\"btn btn-primary oe_kanban_action_button\\"/>\\n                                </t>\\n                                <t t-else=\\"\\">\\n                                    <button type=\\"object\\" name=\\"action_create_vendor_bill\\" class=\\"btn btn-primary d-block\\" journal_type=\\"purchase\\" groups=\\"account.group_account_invoice\\">\\n                                        <span>Upload</span>\\n                                    </button>\\n                                </t>\\n                                <a type=\\"object\\" name=\\"action_create_new\\" class=\\"o_invoice_new\\" groups=\\"account.group_account_invoice\\">Create Manually</a>\\n                            </t>\\n                        </div>\\n                        <div class=\\"col-12 col-sm-7 o_kanban_primary_right\\">\\n                            <div class=\\"row\\" t-if=\\"dashboard.number_draft\\">\\n                                <div class=\\"col overflow-hidden text-start\\">\\n                                    <a t-if=\\"journal_type == 'sale'\\" type=\\"object\\" name=\\"open_action\\" context=\\"{'search_default_draft': '1'}\\">\\n                                        <span title=\\"Invoices to Validate\\"><t t-out=\\"dashboard.number_draft\\"/> Invoices to Validate</span>\\n                                    </a>\\n                                    <a t-if=\\"journal_type == 'purchase'\\" type=\\"object\\" name=\\"open_action\\" context=\\"{'search_default_draft': '1'}\\">\\n                                        <span title=\\"Bills to Validate\\" id=\\"account_dashboard_purchase_draft\\"><t t-out=\\"dashboard.number_draft\\"/> Bills to Validate</span>\\n                                    </a>\\n                                </div>\\n                                <div class=\\"col-auto text-end\\">\\n                                    <span class=\\"o_kanban_monetary\\"><t t-out=\\"dashboard.sum_draft\\"/></span>\\n                                </div>\\n                            </div>\\n                            <div class=\\"row\\" t-if=\\"dashboard.number_waiting\\">\\n                                <div class=\\"col overflow-hidden text-start\\">\\n                                    <a type=\\"object\\" t-if=\\"journal_type == 'sale'\\" name=\\"open_action\\" context=\\"{'search_default_open':1, 'search_default_posted':1, 'search_default_partial': 1}\\" id=\\"account_dashboard_sale_pay_link\\">\\n                                        <t t-out=\\"dashboard.number_waiting\\"/> Unpaid Invoices\\n                                    </a>\\n                                    <a type=\\"object\\" name=\\"open_action\\" t-if=\\"journal_type == 'purchase'\\" context=\\"{'action_name': 'action_open_payment_items', 'search_default_purchases': '1'}\\">\\n                                        <t t-out=\\"dashboard.number_waiting\\"/> Bills to Pay\\n                                    </a>\\n                                </div>\\n                                <div class=\\"col-auto text-end\\">\\n                                    <span class=\\"o_kanban_monetary\\"><t t-out=\\"dashboard.sum_waiting\\"/></span>\\n                                </div>\\n                            </div>\\n                            <div class=\\"row\\" t-if=\\"dashboard.number_late\\">\\n                                <div class=\\"col overflow-hidden text-start\\">\\n                                    <a type=\\"object\\" name=\\"open_action\\" t-if=\\"journal_type == 'sale'\\" context=\\"{'search_default_late': '1'}\\">\\n                                        <span><t t-out=\\"dashboard.number_late\\"/> Late Invoices</span>\\n                                    </a>\\n                                    <a type=\\"object\\" t-if=\\"journal_type == 'purchase'\\" name=\\"open_action\\" context=\\"{'action_name': 'action_open_payment_items', 'search_default_purchases': '1', 'search_default_late': '1'}\\">\\n                                        <span><t t-out=\\"dashboard.number_late\\"/> Late Bills</span>\\n                                    </a>\\n                                </div>\\n                                <div class=\\"col-auto text-end\\">\\n                                    <span class=\\"o_kanban_monetary\\"><t t-out=\\"dashboard.sum_late\\"/></span>\\n                                </div>\\n                            </div>\\n                            <t t-if=\\"dashboard.number_to_check &gt; 0\\">\\n                                <div class=\\"row\\">\\n                                    <div class=\\"col overflow-hidden text-start\\">\\n                                        <a type=\\"object\\" name=\\"open_action\\" context=\\"{'search_default_to_check': True}\\"><t t-out=\\"dashboard.number_to_check\\"/> to check</a>\\n                                    </div>\\n                                    <div class=\\"col-auto text-end\\">\\n                                        <span class=\\"o_kanban_monetary\\"><t t-out=\\"dashboard.to_check_balance\\"/></span>\\n                                    </div>\\n                                </div>\\n                            </t>\\n                        </div>\\n                    </t>\\n                    <t t-name=\\"JournalBodyGraph\\">\\n                        <field name=\\"kanban_dashboard_graph\\" t-att-graph_type=\\"['cash','bank'].includes(journal_type) ? 'line' : 'bar'\\" widget=\\"dashboard_graph\\"/>\\n                    </t>\\n            </templates>\\n            </kanban>"}	<?xml version="1.0"?>\n<kanban create="false" class="o_kanban_dashboard o_account_kanban" banner_route="/onboarding/account_dashboard" js_class="account_dashboard_kanban">\n                <field name="id"/>\n                <field name="name"/>\n                <field name="type"/>\n                <field name="color"/>\n                <field name="show_on_dashboard"/>\n                <field name="kanban_dashboard"/>\n                <field name="activity_ids"/>\n                <field name="activity_state"/>\n                <field name="alias_domain_id"/>\n                <templates>\n                    <t t-name="kanban-box">\n                        <div t-attf-class="d-flex flex-column flex-fill">\n                            <t t-value="JSON.parse(record.kanban_dashboard.raw_value)" t-set="dashboard"/>\n                            <t t-value="record.type.raw_value" t-set="journal_type"/>\n                            <t t-call="JournalTop"/>\n                            <div t-att-class="'container o_kanban_card_content' + (dashboard.is_sample_data ? ' o_sample_data' : '')">\n                                <div class="row">\n                                    <t t-if="(journal_type == 'bank' || journal_type == 'cash')" t-call="JournalBodyBankCash"/>\n                                    <t t-if="journal_type == 'sale' || journal_type == 'purchase'" t-call="JournalBodySalePurchase"/>\n                                    <t t-if="journal_type == 'general'" t-call="JournalMiscelaneous"/>\n                                    <div class="col-12 col-sm-5 mb-3 mb-sm-0 o_kanban_primary_left"/>\n                                    <div class="col-12 col-sm-7 o_kanban_primary_right">\n                                        <t t-call="HasSequenceHoles"/>\n                                    </div>\n                                </div>\n                                <div class="row mt-auto">\n                                    <t t-if="['bank', 'cash', 'sale', 'purchase'].includes(journal_type)" t-call="JournalBodyGraph"/>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n\n                    <t t-name="JournalTop">\n                        <div t-attf-class="o_kanban_card_header">\n                            <div class="o_kanban_card_header_title">\n                                <div class="o_primary">\n                                    <a type="object" name="open_action"><field name="name"/></a>\n                                    <t t-if="dashboard.show_company">\n                                        <span groups="base.group_multi_company" class="small">- <field name="company_id"/></span>\n                                    </t>\n                                </div>\n                                <div class="o_secondary" t-att-title="dashboard.title" t-if="journal_type == 'purchase' &amp;&amp; record.alias_domain_id.raw_value">\n                                    <field name="alias_id"/>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n\n                    <t t-name="HasSequenceHoles">\n                        <a t-if="dashboard.has_sequence_holes" name="show_sequence_holes" type="object" class="text-warning" title="Gaps due to canceled invoices, deleted entries or manual errors in open period.">\n                            Gaps in the sequence\n                        </a>\n                    </t>\n\n                    <t t-name="kanban-menu">\n                        <t t-value="JSON.parse(record.kanban_dashboard.raw_value)" t-set="dashboard"/>\n                        <t t-value="record.type.raw_value" t-set="journal_type"/>\n                        <div class="container">\n                            <!-- For bank and cash -->\n                            <div t-if="journal_type == 'bank' || journal_type == 'cash'" class="row" id="bank_and_cash_container">\n                                <div class="col-4 o_kanban_card_manage_section o_kanban_manage_view">\n                                    <h5 id="card_action_view_menus" class="o_kanban_card_manage_title">\n                                        <span role="separator">View</span>\n                                    </h5>\n                                    <div id="action_card_statements">\n                                        <a t-if="journal_type == 'bank'" role="menuitem" type="object" name="open_action_with_context" context="{'action_name': 'action_bank_statement_tree', 'search_default_journal': True}">Statements</a>\n                                        <a t-if="journal_type == 'cash'" role="menuitem" type="object" name="open_action_with_context" context="{'action_name': 'action_view_bank_statement_tree', 'search_default_journal': True}">Cash Registers</a>\n                                    </div>\n                                    <div>\n                                        <a role="menuitem" type="object" name="open_payments_action">Payments</a>\n                                    </div>\n                                </div>\n\n                                <div class="col-4 o_kanban_card_manage_section o_kanban_manage_new" groups="account.group_account_user">\n                                    <h5 class="o_kanban_card_manage_title">\n                                        <span role="separator">New</span>\n                                    </h5>\n                                    <div t-if="journal_type == 'bank'" name="bank_new_actions">\n                                        <a role="menuitem" type="object" name="action_new_transaction" groups="account.group_account_invoice">New Transaction</a>\n                                    </div>\n                                    <div name="bank_customer_payment">\n                                        <a role="menuitem" type="object" name="create_customer_payment">Customer Payment</a>\n                                    </div>\n                                    <div>\n                                        <a role="menuitem" type="object" name="create_supplier_payment">Vendor Payment</a>\n                                    </div>\n                                </div>\n\n                            </div>\n\n                            <!-- For purchase and sale -->\n                            <div t-if="journal_type == 'purchase' || journal_type == 'sale'" class="row">\n                                <div class="col-4 o_kanban_card_manage_section o_kanban_manage_view">\n                                    <h5 class="o_kanban_card_manage_title">\n                                        <span>View</span>\n                                    </h5>\n                                    <div>\n                                        <a t-if="journal_type == 'sale'" type="object" name="open_action" context="{'action_name': 'action_move_out_invoice_type'}">Invoices</a>\n                                        <a t-if="journal_type == 'purchase'" type="object" name="open_action" context="{'action_name': 'action_move_in_invoice_type'}">Bills</a>\n                                    </div>\n                                    <div id="sale_purchase_refund">\n                                        <a t-if="journal_type == 'sale'" type="object" name="open_action" context="{'action_name': 'action_move_out_refund_type'}">Credit Notes</a>\n                                        <a t-if="journal_type == 'purchase'" type="object" name="open_action" context="{'action_name': 'action_move_in_refund_type'}">Refund</a>\n                                    </div>\n                                    <div>\n                                        <a type="object" name="open_action" context="{'action_name': 'action_account_moves_all_a'}" groups="base.group_no_one">Journal Items</a>\n                                    </div>\n                                </div>\n\n                                <div class="col-4 o_kanban_card_manage_section o_kanban_manage_new" groups="account.group_account_invoice">\n                                    <h5 class="o_kanban_card_manage_title">\n                                        <span>New</span>\n                                    </h5>\n                                    <div>\n                                        <a type="object" name="action_create_new">\n                                            <span t-if="journal_type == 'sale'">Invoice</span>\n                                            <span t-if="journal_type == 'purchase'">Bill</span>\n                                        </a>\n                                    </div>\n                                    <div>\n                                        <a type="object" name="action_create_new" context="{'refund':True}">\n                                            <span t-if="journal_type == 'sale'">Credit Note</span>\n                                            <span t-if="journal_type == 'purchase'">Refund</span>\n                                        </a>\n                                    </div>\n                                    <div t-if="journal_type == 'sale'">\n                                        <widget name="account_file_uploader" title="Upload Invoices" btnClass="file_upload_kanban_action_a"/>\n                                    </div>\n                                </div>\n\n                                <div class="col-4 o_kanban_card_manage_section o_kanban_manage_reports">\n                                    <h5 class="o_kanban_card_manage_title">\n                                        <span>Reporting</span>\n                                    </h5>\n                                    <div>\n                                        <a t-if="journal_type == 'sale'" type="action" name="287" groups="account.group_account_readonly">Invoices Analysis</a>\n                                        <a t-if="journal_type == 'purchase'" type="action" name="286" groups="account.group_account_readonly">Bills Analysis</a>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <!-- For general and situation -->\n                            <div t-if="journal_type == 'general' || journal_type == 'situation'" class="row">\n                                <div class="col-4 o_kanban_card_manage_section o_kanban_manage_view">\n                                    <h5 class="o_kanban_card_manage_title">\n                                        <span>View</span>\n                                    </h5>\n                                    <div>\n                                        <a type="object" name="open_action" context="{'action_name': 'action_move_journal_line'}">Journal Entries</a>\n                                    </div>\n                                    <div>\n                                        <a type="object" name="open_action" context="{'action_name': 'action_move_journal_line', 'search_default_unposted': 1}">Entries to Review</a>\n                                    </div>\n                                    <div>\n                                        <a type="object" name="open_action" context="{'action_name': 'action_account_moves_all_a'}" groups="base.group_no_one">Journal Items</a>\n                                    </div>\n                                </div>\n\n                                <div class="col-4 o_kanban_card_manage_section o_kanban_manage_new" groups="account.group_account_user">\n                                    <h5 class="o_kanban_card_manage_title">\n                                        <span>New</span>\n                                    </h5>\n                                    <div>\n                                        <a type="object" name="action_create_new">Journal Entry</a>\n                                    </div>\n                                </div>\n\n                                <div class="col-4 o_kanban_card_manage_section o_kanban_manage_operations">\n                                    <h5 class="o_kanban_card_manage_title">\n                                        <span>Operations</span>\n                                    </h5>\n                                    <div>\n                                        <a type="object" name="open_action_with_context" context="{'action_name': 'action_validate_account_move', 'search_default_journal': True}" groups="account.group_account_user">Post All Entries</a>\n                                    </div>\n                                </div>\n                            </div>\n\n                            <div t-if="widget.editable" class="o_kanban_card_manage_settings row">\n                                <div class="col-8">\n                                    <ul class="oe_kanban_colorpicker" data-field="color"/>\n                                </div>\n                            </div>\n\n                            <div groups="account.group_account_manager" class="row o_kanban_card_manage_settings">\n                                <field name="show_on_dashboard" widget="boolean_favorite" class="col-6"/>\n                                <div class="col-6 text-end">\n                                    <a class="dropdown-item" t-if="widget.editable" type="edit">Configuration</a>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n\n                    <t t-name="JournalMiscelaneous">\n                        <div class="col-12 col-sm-4 mb-3 mb-sm-0 o_kanban_primary_left">\n                            <button id="new_misc_entry_button" type="object" name="action_create_new" class="btn btn-primary" groups="account.group_account_invoice">\n                                <span>New Entry</span>\n                            </button>\n                        </div>\n                        <div class="col-12 col-sm-8 o_kanban_primary_right">\n                            <field name="json_activity_data" widget="kanban_vat_activity"/>\n                            <t t-if="dashboard.number_to_check &gt; 0">\n                                <div class="row">\n                                    <div class="col overflow-hidden text-start">\n                                        <a type="object" name="open_action" context="{'action_name': 'action_move_journal_line', 'search_default_to_check': True}"><t t-out="dashboard.number_to_check"/> to check</a>\n                                    </div>\n                                    <div class="col-auto text-end">\n                                        <span class="o_kanban_monetary"><t t-out="dashboard.to_check_balance"/></span>\n                                    </div>\n                                </div>\n                            </t>\n                        </div>\n                    </t>\n\n                    <t t-name="JournalBodyBankCash">\n                        <!-- On the left, display :\n                            - A button corresponding to the bank_statements_source, if it wasn't configured, a button for each of them\n                            - If there are statements to reconcile, a link to reconcile them -->\n                        <div id="dashboard_bank_cash_left" class="col-12 col-sm-5 mb-3 mb-sm-0 o_kanban_primary_left">\n                            <t t-if="journal_type == 'bank'">\n                                <t t-if="['undefined', 'online_sync'].includes(dashboard.bank_statements_source)">\n                                    <button name="action_configure_bank_journal" type="object" class="btn btn-primary" groups="account.group_account_invoice">Connect</button>\n                                </t>\n                                <div id="transactions" class="d-flex mt-3 mt-sm-0" style="gap: 5px;">\n                                    <div name="bank_journal_cta" class="w-100">\n                                        <div t-if="['undefined', 'file_import'].includes(dashboard.bank_statements_source)" name="bank_journal_transactions" class="w-100 d-flex" style="gap: 5px;">\n                                            <a id="create_transaction" name="action_new_transaction" type="object" groups="account.group_account_invoice">New Transaction</a>\n                                        </div>\n                                    </div>\n                                </div>\n                            </t>\n                            <t t-if="journal_type == 'cash'">\n                                <button t-if="dashboard.number_to_reconcile == 0" type="object" name="action_new_transaction" class="btn btn-primary" groups="account.group_account_invoice">New Transaction</button>\n                                <a t-if="dashboard.number_to_reconcile &gt; 0" type="object" name="action_new_transaction" class="oe_inline" groups="account.group_account_invoice">New Transaction</a>\n                            </t>\n                        </div>\n                        <!-- On the right, show other common informations/actions -->\n                        <div id="dashboard_bank_cash_right" class="col-12 col-sm-7 o_kanban_primary_right">\n                            <div class="row" t-if="dashboard.nb_lines_bank_account_balance &gt; 0">\n                                <div id="dashboard_bank_cash_balance" class="col overflow-hidden text-start">\n                                    <span>Balance</span>\n                                </div>\n                                <div class="col-auto text-end">\n                                    <span class="o_kanban_monetary"><t t-out="dashboard.account_balance"/></span>\n                                </div>\n                            </div>\n                            <t t-if="dashboard.has_at_least_one_statement and dashboard.account_balance != dashboard.last_balance">\n                                <div class="row" name="latest_statement">\n                                    <div class="col overflow-hidden text-start">\n                                        <span title="Latest Statement">Last Statement</span>\n                                    </div>\n                                    <div class="col-auto text-end">\n                                        <span class="o_kanban_monetary"><t t-out="dashboard.last_balance"/></span>\n                                    </div>\n                                </div>\n                            </t>\n                            <div class="row" t-if="dashboard.nb_lines_outstanding_pay_account_balance &gt; 0">\n                                <div id="dashboard_bank_cash_outstanding_balance" class="col overflow-hidden text-start">\n                                    <span title="Outstanding Payments/Receipts">Payments</span>\n                                </div>\n                                <div class="col-auto text-end">\n                                    <span><t t-out="dashboard.outstanding_pay_account_balance"/></span>\n                                </div>\n                            </div>\n                            <div class="row" t-if="dashboard.nb_misc_operations &gt; 0">\n                                <div id="dashboard_bank_cash_misc_total" class="col text-start">\n                                    <a type="object" name="open_bank_difference_action" t-att-class="dashboard.misc_class">Misc. Operations</a>\n                                </div>\n                                <div class="col-auto text-end">\n                                    <span><t t-out="dashboard.misc_operations_balance"/></span>\n                                </div>\n                            </div>\n                        </div>\n                    </t>\n                    <t t-name="JournalBodySalePurchase" id="account.JournalBodySalePurchase">\n                        <div class="col-12 col-sm-5 mb-3 mb-sm-0 o_kanban_primary_left">\n                            <t t-if="journal_type == 'sale'">\n                                <button type="object" name="action_create_new" class="btn btn-primary o_invoice_new" groups="account.group_account_invoice">\n                                    <span>New Invoice</span>\n                                </button>\n                            </t>\n                            <t t-if="journal_type == 'purchase'">\n                                <t t-if="dashboard.entries_count &gt; 0">\n                                    <widget name="account_file_uploader" btnClass="btn btn-primary oe_kanban_action_button"/>\n                                </t>\n                                <t t-else="">\n                                    <button type="object" name="action_create_vendor_bill" class="btn btn-primary d-block" journal_type="purchase" groups="account.group_account_invoice">\n                                        <span>Upload</span>\n                                    </button>\n                                </t>\n                                <a type="object" name="action_create_new" class="o_invoice_new" groups="account.group_account_invoice">Create Manually</a>\n                            </t>\n                        </div>\n                        <div class="col-12 col-sm-7 o_kanban_primary_right">\n                            <div class="row" t-if="dashboard.number_draft">\n                                <div class="col overflow-hidden text-start">\n                                    <a t-if="journal_type == 'sale'" type="object" name="open_action" context="{'search_default_draft': '1'}">\n                                        <span title="Invoices to Validate"><t t-out="dashboard.number_draft"/> Invoices to Validate</span>\n                                    </a>\n                                    <a t-if="journal_type == 'purchase'" type="object" name="open_action" context="{'search_default_draft': '1'}">\n                                        <span title="Bills to Validate" id="account_dashboard_purchase_draft"><t t-out="dashboard.number_draft"/> Bills to Validate</span>\n                                    </a>\n                                </div>\n                                <div class="col-auto text-end">\n                                    <span class="o_kanban_monetary"><t t-out="dashboard.sum_draft"/></span>\n                                </div>\n                            </div>\n                            <div class="row" t-if="dashboard.number_waiting">\n                                <div class="col overflow-hidden text-start">\n                                    <a type="object" t-if="journal_type == 'sale'" name="open_action" context="{'search_default_open':1, 'search_default_posted':1, 'search_default_partial': 1}" id="account_dashboard_sale_pay_link">\n                                        <t t-out="dashboard.number_waiting"/> Unpaid Invoices\n                                    </a>\n                                    <a type="object" name="open_action" t-if="journal_type == 'purchase'" context="{'action_name': 'action_open_payment_items', 'search_default_purchases': '1'}">\n                                        <t t-out="dashboard.number_waiting"/> Bills to Pay\n                                    </a>\n                                </div>\n                                <div class="col-auto text-end">\n                                    <span class="o_kanban_monetary"><t t-out="dashboard.sum_waiting"/></span>\n                                </div>\n                            </div>\n                            <div class="row" t-if="dashboard.number_late">\n                                <div class="col overflow-hidden text-start">\n                                    <a type="object" name="open_action" t-if="journal_type == 'sale'" context="{'search_default_late': '1'}">\n                                        <span><t t-out="dashboard.number_late"/> Late Invoices</span>\n                                    </a>\n                                    <a type="object" t-if="journal_type == 'purchase'" name="open_action" context="{'action_name': 'action_open_payment_items', 'search_default_purchases': '1', 'search_default_late': '1'}">\n                                        <span><t t-out="dashboard.number_late"/> Late Bills</span>\n                                    </a>\n                                </div>\n                                <div class="col-auto text-end">\n                                    <span class="o_kanban_monetary"><t t-out="dashboard.sum_late"/></span>\n                                </div>\n                            </div>\n                            <t t-if="dashboard.number_to_check &gt; 0">\n                                <div class="row">\n                                    <div class="col overflow-hidden text-start">\n                                        <a type="object" name="open_action" context="{'search_default_to_check': True}"><t t-out="dashboard.number_to_check"/> to check</a>\n                                    </div>\n                                    <div class="col-auto text-end">\n                                        <span class="o_kanban_monetary"><t t-out="dashboard.to_check_balance"/></span>\n                                    </div>\n                                </div>\n                            </t>\n                        </div>\n                    </t>\n                    <t t-name="JournalBodyGraph">\n                        <field name="kanban_dashboard_graph" t-att-graph_type="['cash','bank'].includes(journal_type) ? 'line' : 'bar'" widget="dashboard_graph"/>\n                    </t>\n            </templates>\n            </kanban>\n        	f	t	2026-09-17 06:40:24.625829	2026-09-17 06:40:24.625829	f
