d>\\n                                    <td><span t-field=\\"inv.name\\">INV001</span></td>\\n                                    <td><span t-field=\\"inv.ref\\" data-oe-demo=\\"Sample Ref\\"/></td>\\n                                    <td t-if=\\"otherCurrency\\"/>\\n                                    <td class=\\"text-end\\"><span t-field=\\"inv.amount_total\\">100.00 USD</span></td>\\n                                </tr>\\n                                <!-- PAYMENTS/REVERSALS -->\\n                                <tr t-foreach=\\"inv._get_reconciled_invoices_partials()[0]\\" t-as=\\"par\\">\\n                                    <t t-set=\\"payment\\" t-value=\\"par[2].move_id\\"/>\\n                                    <td><span t-field=\\"payment.date\\">2023-01-05</span></td>\\n                                    <td><span t-field=\\"payment.name\\">PAY001</span></td>\\n                                    <td><span t-field=\\"payment.ref\\" data-oe-demo=\\"Payment Ref\\"/></td>\\n                                    <t t-set=\\"amountPayment\\" t-value=\\"-(par[0].debit_amount_currency if par[2].debit &gt; 0 else par[0].credit_amount_currency)\\"/>\\n                                    <t t-set=\\"amountInvoice\\" t-value=\\"-par[1]\\"/>\\n                                    <t t-set=\\"currencyPayment\\" t-value=\\"payment.currency_id\\"/>\\n                                    <t t-set=\\"currencyInvoice\\" t-value=\\"inv.currency_id\\"/>\\n                                    <!-- Fill the column \\"Amount In Currency\\" only if necessary -->\\n                                    <td t-if=\\"otherCurrency\\" class=\\"text-end\\"><span t-if=\\"currencyPayment != currencyInvoice\\" t-out=\\"amountPayment\\" t-options=\\"{'widget': 'monetary', 'display_currency': currencyPayment}\\">50.00 EUR</span></td>\\n                                    <td class=\\"text-end\\"><span t-out=\\"amountInvoice\\" t-options=\\"{'widget': 'monetary', 'display_currency': currencyInvoice}\\">25.00 USD</span></td>\\n                                </tr>\\n                                <!-- BALANCE -->\\n                                <tr>\\n                                    <td/>\\n                                    <td><strong>Due Amount for <span t-field=\\"inv.name\\">INV001</span></strong></td>\\n                                    <td/>\\n                                    <td t-if=\\"otherCurrency\\"/>\\n                                    <td class=\\"text-end\\"><strong><span t-field=\\"inv.amount_residual\\">25.0 USD</span></strong></td>\\n                                </tr>\\n                            </t>\\n                        </t>\\n                    </tbody>\\n                </table>\\n            </div>\\n            <div class=\\"oe_structure\\"/>\\n        </t>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="account.report_payment_receipt_document">\n        <t t-call="web.external_layout">\n            <t t-set="o" t-value="o.with_context(lang=lang)"/>\n            <t t-set="values" t-value="o._get_payment_receipt_report_values()"/>\n            <div class="page">\n                <h3><strong id="payment_title">Payment Receipt: <span t-field="o.name">INV0001</span></strong></h3>\n\n                <div class="mb-4 mt-3">\n                    <div name="date" class="row">\n                        <div class="col-6" t-if="o.date">\n                            Payment Date: <span t-field="o.date">2023-01-01</span>\n                        </div>\n                    </div>\n                    <div class="oe_structure"/>\n                    <div class="row">\n                        <div class="col-6" t-if="o.partner_type">\n                            <t t-if="o.partner_type == 'customer'">\n                                Customer:\n                            </t>\n                            <t t-else="o.partner_type == 'supplier'">\n                                Vendor:\n                            </t><span t-field="o.partner_id" data-oe-demo="Marc Demo"/>\n                        </div>\n                        <div name="payment_method" t-if="values['display_payment_method'] and o.payment_method_id" class="col-6">\n                            Payment Method: <span t-field="o.payment_method_id.name">Credit card</span>\n                        </div>\n                    </div>\n                    <div class="oe_structure"/>\n                    <div class="row">\n                        <div class="col-6" t-if="o.amount">\n                            Payment Amount: <span t-field="o.amount" t-options="{'widget': 'monetary', 'display_currency': o.currency_id}">50 USD</span>\n                         </div>\n                        <div class="col-6" t-if="o.ref">\n                            Memo: <span t-field="o.ref">Sample Memo</span>\n                         </div>\n                    </div>\n                </div>\n\n                <div class="oe_structure"/>\n                <table name="invoices" t-if="values['display_invoices']" class="table table-sm">\n                    <t t-set="invoices" t-value="o.reconciled_invoice_ids or o.reconciled_bill_ids"/>\n                    <!-- Check if invoices include different currencies -->\n                    <t t-foreach="invoices" t-as="inv">\n                        <t t-if="any(inv.currency_id != par[2].currency_id for par in inv._get_reconciled_invoices_partials()[0])" t-set="otherCurrency" t-value="True"/>\n                    </t>\n                    <thead>\n                        <tr>\n                            <th><span>Invoice Date</span></th>\n                            <th><span>Invoice Number</span></th>\n                            <th><span>Reference</span></th>\n                            <!-- Add a column if there are different currencies -->\n                            <th t-if="otherCurrency" class="text-end"><span>Amount In Currency</span></th>\n                            <th class="text-end"><span>Amount</span></th>\n                        </tr>\n                    </thead>\n                    <tbody>\n                        <t t-foreach="invoices" t-as="inv">\n                            <!-- MOVE -->\n                            <t t-if="inv.move_type != 'entry'">\n                                <tr>\n                                    <td><span t-field="inv.invoice_date">2023-01-01</span></td>\n                                    <td><span t-field="inv.name">INV001</span></td>\n                                    <td><span t-field="inv.ref" data-oe-demo="Sample Ref"/></td>\n                                    <td t-if="otherCurrency"/>\n                                    <td class="text-end"><span t-field="inv.amount_total">100.00 USD</span></td>\n                                </tr>\n                                <!-- PAYMENTS/REVERSALS -->\n                                <tr t-foreach="inv._get_reconciled_invoices_partials()[0]" t-as="par">\n                                    <t t-set="payment" t-value="par[2].move_id"/>\n                                    <td><span t-field="payment.date">2023-01-05</span></td>\n                                    <td><span t-field="payment.name">PAY001</span></td>\n                                    <td><span t-field="payment.ref" data-oe-demo="Payment Ref"/></td>\n                                    <t t-set="amountPayment" t-value="-(par[0].debit_amount_currency if par[2].debit &gt; 0 else par[0].credit_amount_currency)"/>\n                                    <t t-set="amountInvoice" t-value="-par[1]"/>\n                                    <t t-set="currencyPayment" t-value="payment.currency_id"/>\n                                    <t t-set="currencyInvoice" t-value="inv.currency_id"/>\n                                    <!-- Fill the column "Amount In Currency" only if necessary -->\n                                    <td t-if="otherCurrency" class="text-end"><span t-if="currencyPayment != currencyInvoice" t-out="amountPayment" t-options="{'widget': 'monetary', 'display_currency': currencyPayment}">50.00 EUR</span></td>\n                                    <td class="text-end"><span t-out="amountInvoice" t-options="{'widget': 'monetary', 'display_currency': currencyInvoice}">25.00 USD</span></td>\n                                </tr>\n                                <!-- BALANCE -->\n                                <tr>\n                                    <td/>\n                                    <td><strong>Due Amount for <span t-field="inv.name">INV001</span></strong></td>\n                                    <td/>\n                                    <td t-if="otherCurrency"/>\n                                    <td class="text-end"><strong><span t-field="inv.amount_residual">25.0 USD</span></strong></td>\n                                </tr>\n                            </t>\n                        </t>\n                    </tbody>\n                </table>\n            </div>\n            <div class="oe_structure"/>\n        </t>\n    </t>\n\n    	f	t	2026-09-17 06:40:24.625829	2026-09-17 06:40:24.625829	f
