815	16	\N	1	1	stock_report_delivery_has_serial_move_line	\N	stock.stock_report_delivery_has_serial_move_line	qweb	stock/report/report_deliveryslip.xml	primary	{"en_US": "<t t-name=\\"stock.stock_report_delivery_has_serial_move_line\\">\\n        <td>\\n            <span t-field=\\"move_line.product_id\\"/>\\n            <!-- this is an annoying workaround for the multiple types of descriptions (often auto-filled) that we do not want to print -->\\n            <!-- this makes it so we can pre-filter the descriptions in inherited templates since we cannot extend the standard \\"if\\" condition -->\\n            <!-- let's agree that pre-filtered descriptions will be set to \\"\\" -->\\n            <t t-if=\\"not description and description != ''\\">\\n                <t t-set=\\"description\\" t-value=\\"move_line.move_id.description_picking\\"/>\\n            </t>\\n            <p t-if=\\"description != '' and                      description != move_line.product_id.display_name and                      description != move_line.product_id.name\\">\\n                <span t-esc=\\"description\\"/>\\n            </p>\\n        </td>\\n        <t t-if=\\"has_serial_number\\" name=\\"move_line_lot\\">\\n            <td><span t-field=\\"move_line.lot_id.name\\"/></td>\\n        </t>\\n        <td class=\\"text-center\\" name=\\"move_line_lot_quantity\\">\\n            <span t-field=\\"move_line.quantity\\"/>\\n            <span t-field=\\"move_line.product_uom_id\\"/>\\n            <span t-if=\\"move_line.move_id.product_packaging_id\\" groups=\\"product.group_stock_packaging\\">\\n                (<span t-field=\\"move_line.product_packaging_qty\\" t-options=\\"{&quot;widget&quot;: &quot;integer&quot;}\\"/> <span t-field=\\"move_line.move_id.product_packaging_id.display_name\\"/>)\\n            </span>\\n        </td>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="stock.stock_report_delivery_has_serial_move_line">\n        <td>\n            <span t-field="move_line.product_id"/>\n            <!-- this is an annoying workaround for the multiple types of descriptions (often auto-filled) that we do not want to print -->\n            <!-- this makes it so we can pre-filter the descriptions in inherited templates since we cannot extend the standard "if" condition -->\n            <!-- let's agree that pre-filtered descriptions will be set to "" -->\n            <t t-if="not description and description != ''">\n                <t t-set="description" t-value="move_line.move_id.description_picking"/>\n            </t>\n            <p t-if="description != '' and                      description != move_line.product_id.display_name and                      description != move_line.product_id.name">\n                <span t-esc="description"/>\n            </p>\n        </td>\n        <t t-if="has_serial_number" name="move_line_lot">\n            <td><span t-field="move_line.lot_id.name"/></td>\n        </t>\n        <td class="text-center" name="move_line_lot_quantity">\n            <span t-field="move_line.quantity"/>\n            <span t-field="move_line.product_uom_id"/>\n            <span t-if="move_line.move_id.product_packaging_id" groups="product.group_stock_packaging">\n                (<span t-field="move_line.product_packaging_qty" t-options="{&quot;widget&quot;: &quot;integer&quot;}"/> <span t-field="move_line.move_id.product_packaging_id.display_name"/>)\n            </span>\n        </td>\n    </t>\n    	f	t	2026-09-17 06:40:30.720062	2026-09-17 06:40:30.720062	f
