ies\\" domain=\\"[('picking_type_code', '=', 'outgoing')]\\"/>\\n                    <filter name=\\"internal\\" string=\\"Internal\\" domain=\\"[('picking_type_code', '=', 'internal')]\\"/>\\n                    <separator/>\\n                    <filter name=\\"late\\" string=\\"Late\\" help=\\"Deadline exceed or/and by the scheduled\\" domain=\\"[('state', 'in', ('assigned', 'waiting', 'confirmed')), '|', '|', ('has_deadline_issue', '=', True), ('date_deadline', '&lt;', current_date), ('scheduled_date', '&lt;', current_date)]\\"/>\\n                    <filter string=\\"Planning Issues\\" name=\\"planning_issues\\" help=\\"Transfers that are late on scheduled time or one of pickings will be late\\" domain=\\"['|', ('delay_alert_date', '!=', False), '&amp;', ('scheduled_date','&lt;', time.strftime('%Y-%m-%d %H:%M:%S')), ('state', 'in', ('assigned', 'waiting', 'confirmed'))]\\"/>\\n                    <separator/>\\n                    <filter name=\\"backorder\\" string=\\"Backorders\\" domain=\\"[('backorder_id', '!=', False), ('state', 'in', ('assigned', 'waiting', 'confirmed'))]\\" help=\\"Remaining parts of picking partially processed\\"/>\\n                    <separator/>\\n                    <filter invisible=\\"1\\" string=\\"Late Activities\\" name=\\"activities_overdue\\" domain=\\"[('my_activity_date_deadline', '&lt;', context_today().strftime('%Y-%m-%d'))]\\" help=\\"Show all records which has next action date is before today\\"/>\\n                    <filter invisible=\\"1\\" string=\\"Today Activities\\" name=\\"activities_today\\" domain=\\"[('my_activity_date_deadline', '=', context_today().strftime('%Y-%m-%d'))]\\"/>\\n                    <filter invisible=\\"1\\" string=\\"Future Activities\\" name=\\"activities_upcoming_all\\" domain=\\"[('my_activity_date_deadline', '&gt;', context_today().strftime('%Y-%m-%d'))]\\"/>\\n                    <separator/>\\n                    <filter string=\\"Warnings\\" name=\\"activities_exception\\" domain=\