ort_22">\n            <t xmlns:ram="urn:un:unece:uncefact:data:standard:ReusableAggregateBusinessInformationEntity:100" xmlns:rsm="urn:un:unece:uncefact:data:standard:CrossIndustryInvoice:100" xmlns:udt="urn:un:unece:uncefact:data:standard:UnqualifiedDataType:100" xmlns:qdt="urn:un:unece:uncefact:data:standard:QualifiedDataType:100" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">\n                <!-- Contact. -->\n                <ram:Name t-out="partner.display_name if partner.name else partner.commercial_partner_id.display_name"/>\n                <ram:SpecifiedLegalOrganization t-if="specified_legal_organization_val">\n                    <ram:ID t-att-schemeID="str('0002')" t-out="specified_legal_organization_val"/>\n                </ram:SpecifiedLegalOrganization>\n\n                <ram:DefinedTradeContact t-if="not hide_dtc">\n                    <ram:PersonName t-out="partner.name"/>\n                    <ram:TelephoneUniversalCommunication t-if="partner.phone or partner.mobile">\n                        <ram:CompleteNumber t-out="partner.phone or partner.mobile"/>\n                    </ram:TelephoneUniversalCommunication>\n                    <ram:EmailURIUniversalCommunication t-if="partner.email">\n                        <ram:URIID t-out="partner.email"/>\n                    </ram:EmailURIUniversalCommunication>\n                </ram:DefinedTradeContact>\n\n                <!-- Address. -->\n                <t t-call="account_edi_ubl_cii.account_invoice_address_facturx_export_22"/>\n            </t>\n        </t>\n\n        	f	t	2026-09-17 06:40:35.368357	2026-09-17 06:40:35.368357	f
